INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('1f8d26ff-3722-452c-9ab5-2b27c8f4e914', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'component', 'chart-heatmap', 'ChartHeatmap', 'Data Display', NULL, 'mdi-grid', 'components.catalog.chart_heatmap.description', 'Rectangular heatmap chart. Renders a grid of SVG <rect> cells coloured by value via CSS color-mix interpolation. Common uses: GitHub activity grids, correlation matrices, weekday × hour patterns.', NULL, NULL, 'origam-chart-heatmap', NULL, 'packages/ds/src/components/Chart/OrigamChartHeatmap.vue', 'origam', NULL, NULL, '/stories/?story=components-chart-heatmap--design', '/docs/components/Chart/OrigamChartHeatmap.html', 'chart', '{"a11y": {"notes": [{"noteKey": "components.chart_heatmap.a11y.figure_role", "noteFallback": "Root has role=\"figure\" with aria-label from the title prop (falls back to \"heatmap chart\")."}, {"noteKey": "components.chart_heatmap.a11y.svg_role", "noteFallback": "The SVG carries role=\"img\" with a <title> and <desc> listing column and row counts."}, {"noteKey": "components.chart_heatmap.a11y.cell_aria", "noteFallback": "Each cell has aria-label in the format \"xCat × yCat: value\" for screen reader announcement."}, {"noteKey": "components.chart_heatmap.a11y.reduced_motion", "noteFallback": "Entry animations are disabled via @media (prefers-reduced-motion: reduce)."}], "roles": ["figure", "img", "button"], "keyboard": [{"key": "Tab", "actionKey": "components.chart_heatmap.a11y.key_tab", "actionFallback": "Moves focus through each cell (tabindex=\"0\")."}, {"key": "Enter / Space", "actionKey": "components.chart_heatmap.a11