INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('6cbd46f9-b9a5-4cb0-a514-1999196ec796', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'component', 'color-picker', 'ColorPicker', 'Form & Input', NULL, 'mdi-palette', 'components.catalog.color_picker.description', 'Full-featured HSVA colour picker. Includes a gradient canvas, hue/alpha sliders, hex/RGB/HSL/HSV input fields and optional swatches. Composes OrigamColorPickerCanvas, OrigamColorPickerPreview, OrigamColorPickerEdit and OrigamColorPickerSwatches.', NULL, NULL, 'origam-color-picker', NULL, 'packages/ds/src/components/ColorPicker/OrigamColorPicker.vue', 'origam', NULL, NULL, '/stories/?story=components-colorpicker--design', '/docs/components/ColorPicker/OrigamColorPicker.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.color_picker.a11y.canvas_label", "noteFallback": "The canvas carries an aria-label describing the gradient region. The drag cursor position is announced via aria-valuemin/valuemax/valuenow attributes."}, {"noteKey": "components.color_picker.a11y.input_labels", "noteFallback": "Each text input has a visible label matching the mode (HEX, R, G, B, H, S, L…). Screen readers read the label and current value together."}], "roles": ["group"], "keyboard": [{"key": "Tab", "actionKey": "components.color_picker.a11y.key_tab", "actionFallback": "Moves focus between canvas, sliders, input fields and mode switcher."}, {"key": "Arrow keys (canvas)", "actionKey": "components.color_picker.a11y.key_canvas_arrows", "actionFallback": "Moves the canvas cursor by 1% increments in saturation/value. Allows precise colour selection without a mouse."}, {"key": "Arrow keys (sliders)", "actionKey": "components.color_picker.a11y.key_slider_arrows", "actionFallback": "Adjusts the hue or alpha slider value by 1 step."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-space---2)", "tokenPath": "--origam-color-picker__edit---gap", "descriptionKey": "components.color_picker.tokens.edit_gap", "descriptionFallback": "Gap between edit input fields."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"300\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"175\" y=\"20\" width=\"350\" height=\"260\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"183\" y=\"28\" width=\"334\" height=\"120\" rx=\"4\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" opacity=\"0.7\"/>\n  <circle cx=\"310\" cy=\"88\" r=\"8\" fill=\"white\" stroke=\"white\" stroke-width=\"2\" opacity=\"0.9\"/>\n  <rect x=\"183\" y=\"156\" width=\"334\" height=\"24\" rx=\"4\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.06))\"/>\n  <rect x=\"195\" y=\"162\" width=\"28\" height=\"12\" rx=\"6\" fill=\"#7c3aed\"/>\n  <rect x=\"233\" y=\"162\" width=\"270\" height=\"12\" rx=\"6\" fill=\"linear-gradient(to right, red, blue)\"/>\n  <rect x=\"183\" y=\"186\" width=\"334\" height=\"24\" rx=\"4\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.04))\"/>\n  <text x=\"350\" y=\"202\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">HEX / RGB / HSL inputs</text>\n  <rect x=\"183\" y=\"218\" width=\"334\" height=\"52\" rx=\"4\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.04))\"/>\n  <text x=\"350\" y=\"248\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"sans-serif\">Swatches (optional)</text>\n  <circle cx=\"183\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"183\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"310\" cy=\"80\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"310\" y=\"84\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"195\" cy=\"156\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"195\" y=\"160\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"350\" cy=\"180\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"350\" y=\"184\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"350\" cy=\"212\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"350\" y=\"216\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <circle cx=\"350\" cy=\"265\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"350\" y=\"269\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n  <text x=\"350\" y=\"290\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">Each sub-component emits update:colorHsv — changes bubble up to OrigamColorPicker</text>\n", "code": "<origam-picker class=\"origam-color-picker\">\n  <!-- canvas (drag cursor to pick S+V) -->\n  <origam-color-picker-canvas\n    :color-hsv=\"currentColor\"\n    :height=\"canvasHeight\"\n    @update:color-hsv=\"handleUpdateColor\"\n  />\n\n  <!-- controls: preview sliders + input fields -->\n  <div class=\"origam-color-picker__controls\">\n    <origam-color-picker-preview\n      :color-hsv=\"currentColor\"\n      :hide-alpha=\"!mode.endsWith(''a'')\"\n      @update:color-hsv=\"handleUpdateColor\"\n    />\n    <origam-color-picker-edit\n      :color-hsv=\"currentColor\"\n      :mode=\"mode\"\n      :modes=\"modes\"\n      @update:mode=\"handleUpdateMode\"\n      @update:color-hsv=\"handleUpdateColor\"\n    />\n  </div>\n\n  <!-- swatches grid (optional) -->\n  <origam-color-picker-swatches\n    v-if=\"showSwatches\"\n    :color-hsv=\"currentColor\"\n    @update:color-hsv=\"handleUpdateColor\"\n  />\n\n  <!-- #actions slot forwarded from OrigamPicker -->\n  <template #actions>\n    <slot name=\"actions\" />\n  </template>\n</origam-picker>", "legend": [{"cls": ".origam-color-picker", "num": 1, "descriptionKey": "components.color_picker.anatomy.root", "descriptionFallback": "Root element wrapping OrigamPicker. Inherits picker chrome (title, header, actions slots)."}, {"cls": ".origam-color-picker-canvas", "num": 2, "descriptionKey": "components.color_picker.anatomy.canvas", "descriptionFallback": "Gradient canvas (OrigamColorPickerCanvas). Drag to change saturation + value. Hidden when hideCanvas=true."}, {"cls": ".origam-color-picker-preview", "num": 3, "descriptionKey": "components.color_picker.anatomy.preview", "descriptionFallback": "Hue and alpha sliders + preview swatch (OrigamColorPickerPreview). Hidden when hideSliders=true."}, {"cls": ".origam-color-picker__controls", "num": 4, "descriptionKey": "components.color_picker.anatomy.controls", "descriptionFallback": "Row grouping the preview strip and edit inputs."}, {"cls": ".origam-color-picker-edit", "num": 5, "descriptionKey": "components.color_picker.anatomy.edit", "descriptionFallback": "Input fields + mode switcher (OrigamColorPickerEdit). Hidden when hideInputs=true."}, {"cls": ".origam-color-picker-swatches", "num": 6, "descriptionKey": "components.color_picker.anatomy.swatches", "descriptionFallback": "Predefined swatch grid (OrigamColorPickerSwatches). Visible only when showSwatches=true."}], "classes": [{"cls": "origam-color-picker", "descriptionKey": "components.color_picker.anatomy.root", "descriptionFallback": "Root picker panel."}, {"cls": "origam-color-picker__controls", "descriptionKey": "components.color_picker.anatomy.controls", "descriptionFallback": "Row grouping preview sliders + inputs."}, {"cls": "origam-color-picker-canvas", "descriptionKey": "components.color_picker.anatomy.canvas", "descriptionFallback": "Gradient canvas sub-component."}, {"cls": "origam-color-picker-preview", "descriptionKey": "components.color_picker.anatomy.preview", "descriptionFallback": "Hue/alpha sliders + preview swatch."}, {"cls": "origam-color-picker-edit", "descriptionKey": "components.color_picker.anatomy.edit", "descriptionFallback": "HEX/RGB/HSL/HSV input fields."}, {"cls": "origam-color-picker-swatches", "descriptionKey": "components.color_picker.anatomy.swatches", "descriptionFallback": "Predefined colour swatches grid."}], "svgDesc": "Schematic of the ColorPicker with 6 numbered internal parts.", "svgTitle": "Anatomy of OrigamColorPicker", "rootClass": "origam-color-picker", "figcaption": "Anatomy of <code>&lt;origam-color-picker&gt;</code> — 6 composable regions.", "svgViewBox": "0 0 700 300"}, "cssVars": [{"name": "--origam-color-picker---background-color", "defaultValue": "{color.surface.raised}", "descriptionKey": "components.color_picker.css_vars.bg", "descriptionFallback": "Picker panel background colour."}, {"name": "--origam-color-picker---border-radius", "defaultValue": "{radius.md}", "descriptionKey": "components.color_picker.css_vars.border_radius", "descriptionFallback": "Picker panel corner radius."}, {"name": "--origam-color-picker---min-width", "defaultValue": "300px", "descriptionKey": "components.color_picker.css_vars.min_width", "descriptionFallback": "Minimum width of the picker panel."}, {"name": "--origam-color-picker__canvas---border-radius", "defaultValue": "{radius.sm}", "descriptionKey": "components.color_picker.css_vars.canvas_border_radius", "descriptionFallback": "Canvas corner radius."}, {"name": "--origam-color-picker__cursor---size", "defaultValue": "16px", "descriptionKey": "components.color_picker.css_vars.cursor_size", "descriptionFallback": "Size of the drag cursor circle on the canvas."}, {"name": "--origam-color-picker__preview---width", "defaultValue": "32px", "descriptionKey": "components.color_picker.css_vars.preview_width", "descriptionFallback": "Width of the current colour preview swatch."}, {"name": "--origam-color-picker__preview---height", "defaultValue": "32px", "descriptionKey": "components.color_picker.css_vars.preview_height", "descriptionFallback": "Height of the current colour preview swatch."}, {"name": "--origam-color-picker__swatches---item-size", "defaultValue": "20px", "descriptionKey": "components.color_picker.css_vars.swatches_item_size", "descriptionFallback": "Size of each swatch tile."}, {"name": "--origam-color-picker__hue-slider---height", "defaultValue": "12px", "descriptionKey": "components.color_picker.css_vars.hue_slider_height", "descriptionFallback": "Height of the hue slider track."}, {"name": "--origam-color-picker__alpha-slider---height", "defaultValue": "12px", "descriptionKey": "components.color_picker.css_vars.alpha_slider_height", "descriptionFallback": "Height of the alpha slider track."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.color_picker.exposed.filter_props", "descriptionFallback": "Utility to forward filtered props to OrigamPicker or sub-components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.color_picker.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.color_picker.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.color_picker.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.color_picker.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.color_picker.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "switch", "prop": "hideCanvas", "labelKey": "components.color_picker.playground.hide_canvas", "defaultValue": false, "labelFallback": "Hide canvas"}, {"kind": "switch", "prop": "hideSliders", "labelKey": "components.color_picker.playground.hide_sliders", "defaultValue": false, "labelFallback": "Hide sliders"}, {"kind": "switch", "prop": "hideInputs", "labelKey": "components.color_picker.playground.hide_inputs", "defaultValue": false, "labelFallback": "Hide inputs"}, {"kind": "switch", "prop": "showSwatches", "labelKey": "components.color_picker.playground.show_swatches", "defaultValue": false, "labelFallback": "Show swatches"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.color_picker.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
