INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('75fb3f96-ca5c-4cd1-9495-5ad110c3cc39', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'component', 'data-table-rows', 'DataTableRows', 'Data Display', NULL, 'mdi-table-multiple', 'components.catalog.data_table_rows.description', 'Container that iterates data items and renders DataTableRow, group header rows, skeleton/loading rows, and an empty-state row.', NULL, NULL, 'origam-data-table-rows', NULL, 'packages/ds/src/components/DataTable/OrigamDataTableRows.vue', 'origam', NULL, NULL, '/stories/?story=components-datatable--design', '/docs/components/DataTable/OrigamDataTable.html', 'data-table', '{"a11y": {"notes": [{"noteKey": "components.data_table_rows.a11y.aria_busy", "noteFallback": "Skeleton placeholder rows expose <code>aria-busy=\"true\"</code> on each <code>&lt;tr&gt;</code> to signal screen readers that content is loading."}, {"noteKey": "components.data_table_rows.a11y.aria_rowindex", "noteFallback": "<code>aria-rowindex</code> is set on each data row (startIndex + index + 2) to give screen readers accurate row position information in paginated tables."}, {"noteKey": "components.data_table_rows.a11y.no_data", "noteFallback": "The empty-state row uses a <code>&lt;td colspan&gt;</code> spanning all columns, with centred text. Override the no-data slot to provide a more descriptive message for screen reader users."}], "roles": ["rowgroup"], "keyboard": [{"key": "Tab", "actionKey": "components.data_table_rows.a11y.key_tab", "actionFallback": "Moves focus through interactive elements inside rows (checkboxes, expand buttons, clickable cells)."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---default)", "tokenPath": "--origam-data-table-row---background-color", "descriptionKey": "components.data_table_rows.tokens.row_background_color", "descriptionFallback": "Default row background."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"560\" height=\"160\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"16\" y=\"16\" width=\"528\" height=\"36\" rx=\"0\" fill=\"var(--origam-color__surface---default, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"40\" y=\"38\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" font-family=\"''JetBrains Mono'',monospace\">origam-data-table-row (data item)</text>\n  <rect x=\"16\" y=\"56\" width=\"528\" height=\"36\" rx=\"0\" fill=\"var(--origam-color__surface---default, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"40\" y=\"78\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" font-family=\"''JetBrains Mono'',monospace\">origam-data-table-group-header-row (group)</text>\n  <rect x=\"16\" y=\"96\" width=\"528\" height=\"28\" rx=\"0\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1.5\" stroke-dasharray=\"5 3\"/>\n  <text x=\"280\" y=\"114\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-style=\"italic\" font-family=\"''JetBrains Mono'',monospace\">origam-data-table-rows--no-data</text>\n  <rect x=\"16\" y=\"128\" width=\"528\" height=\"16\" rx=\"0\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\" stroke-dasharray=\"5 3\"/>\n  <rect x=\"16\" y=\"128\" width=\"300\" height=\"16\" rx=\"0\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.18))\"/>\n  <circle cx=\"24\" cy=\"24\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"24\" y=\"28\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"24\" cy=\"64\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"24\" y=\"68\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"24\" cy=\"108\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"24\" y=\"112\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"24\" cy=\"136\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"24\" y=\"140\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n", "code": "<!-- data items -->\n<template v-for=\"(item, index) in items\">\n  <!-- group header row -->\n  <template v-if=\"item.type === ''group''\">\n    <slot name=\"group-header\" v-bind=\"groupHeaderSlotProps(item, index)\">\n      <origam-data-table-group-header-row v-bind=\"groupHeaderSlotProps(item, index)\" />\n    </slot>\n  </template>\n  <!-- data row -->\n  <template v-else>\n    <slot name=\"item\" v-bind=\"itemSlotProps(item, index)\">\n      <origam-data-table-row :item=\"item\" v-bind=\"itemSlotProps(item, index).props\" />\n    </slot>\n    <!-- expanded row -->\n    <template v-if=\"isExpanded(item)\">\n      <slot name=\"expanded-row\" v-bind=\"slotProps\" />\n    </template>\n  </template>\n</template>\n\n<!-- skeleton loading rows -->\n<tr v-for=\"rowIndex in 5\" class=\"origam-data-table-rows origam-data-table-rows--skeleton\" aria-busy=\"true\">\n  <td v-for=\"col in columns\" class=\"origam-data-table-rows__skeleton-cell\">\n    <origam-skeleton variant=\"text\" :loading=\"true\" />\n  </td>\n</tr>\n\n<!-- text loading row -->\n<tr class=\"origam-data-table-rows origam-data-table-rows--loading\">\n  <td :colspan=\"columns.length\"><slot name=\"loading\">{{ loadingText }}</slot></td>\n</tr>\n\n<!-- empty state row -->\n<tr class=\"origam-data-table-rows origam-data-table-rows--no-data\">\n  <td :colspan=\"columns.length\"><slot name=\"no-data\">{{ noDataText }}</slot></td>\n</tr>", "legend": [{"cls": "OrigamDataTableRow", "num": 1, "descriptionKey": "components.data_table_rows.anatomy.data_row", "descriptionFallback": "Standard <code>OrigamDataTableRow</code> rendered for each flat data item. Receives computed <code>itemSlotProps.props</code> including key, onClick, mobileBreakpoint and aria-rowindex."}, {"cls": "OrigamDataTableGroupHeaderRow", "num": 2, "descriptionKey": "components.data_table_rows.anatomy.group_row", "descriptionFallback": "<code>OrigamDataTableGroupHeaderRow</code> rendered for group items (type === \"group\"). Receives toggleGroup, isGroupOpen and selection/expand context."}, {"cls": ".origam-data-table-rows--no-data", "num": 3, "descriptionKey": "components.data_table_rows.anatomy.no_data", "descriptionFallback": "Single full-width row rendered when items is empty and hideNoData=false. Text aligned center via --origam-data-table-empty---text-align."}, {"cls": ".origam-data-table-rows--skeleton / --loading", "num": 4, "descriptionKey": "components.data_table_rows.anatomy.skeleton", "descriptionFallback": "Loading state rows. Skeleton mode: 5 <code>&lt;tr aria-busy=\"true\"&gt;</code> rows with one <code>OrigamSkeleton</code> per cell. Text mode: single row with localised loading text."}], "classes": [{"cls": "origam-data-table-rows", "descriptionKey": "components.data_table_rows.anatomy.root", "descriptionFallback": "Applied to the skeleton, loading and no-data tr elements."}, {"cls": "origam-data-table-rows--no-data", "descriptionKey": "components.data_table_rows.anatomy.no_data_class", "descriptionFallback": "Empty state row. Text colour: --origam-data-table-rows--no-data---color."}, {"cls": "origam-data-table-rows--loading", "descriptionKey": "components.data_table_rows.anatomy.loading_class", "descriptionFallback": "Text loading row (non-skeleton). Text colour: --origam-data-table-rows--loading---color."}, {"cls": "origam-data-table-rows--skeleton", "descriptionKey": "components.data_table_rows.anatomy.skeleton_class", "descriptionFallback": "Skeleton loading row (aria-busy=\"true\"). One of 5 placeholder rows."}, {"cls": "origam-data-table-rows__skeleton-cell", "descriptionKey": "components.data_table_rows.anatomy.skeleton_cell", "descriptionFallback": "Cell inside a skeleton row. Contains OrigamSkeleton variant=\"text\"."}], "svgDesc": "Schematic of DataTableRows with 4 internal state variants.", "svgTitle": "Anatomy of OrigamDataTableRows", "rootClass": "origam-data-table-rows", "figcaption": "Anatomy of <code>&lt;origam-data-table-rows&gt;</code> — 4 output variants: data row ①, group header row ②, empty state ③, and skeleton/loading ④.", "svgViewBox": "0 0 560 160"}, "cssVars": [{"name": "--origam-data-table-rows--no-data---color", "defaultValue": "var(--origam-color__text---secondary)", "descriptionKey": "components.data_table_rows.css_vars.no_data_color", "descriptionFallback": "Text colour of the empty-state row."}, {"name": "--origam-data-table-rows--loading---color", "defaultValue": "var(--origam-color__text---secondary)", "descriptionKey": "components.data_table_rows.css_vars.loading_color", "descriptionFallback": "Text colour of the text loading row."}, {"name": "--origam-data-table-empty---text-align", "defaultValue": "center", "descriptionKey": "components.data_table_rows.css_vars.empty_text_align", "descriptionFallback": "Text alignment of the empty-state content."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.data_table_rows.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child row components."}], "playground": {"controls": [{"kind": "switch", "prop": "hideNoData", "labelKey": "components.data_table_rows.playground.hide_no_data", "defaultValue": false, "labelFallback": "Hide No Data"}, {"kind": "switch", "prop": "mobile", "labelKey": "components.data_table_rows.playground.mobile", "defaultValue": false, "labelFallback": "Mobile"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
