ed)\"/>\n  <text x=\"88\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"408\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"408\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n", "code": "<!-- OrigamExpandY — JS-driven <transition> -->\n<transition\n  name=\"origam-transition--expand-y\"\n  mode=\"in-out\"\n  :css=\"!disabled\"\n  @before-enter=\"handleBeforeEnter\"\n  @enter=\"handleEnter\"\n  @after-enter=\"handleAfterEnter\"\n  @enter-cancelled=\"handleEnterCancelled\"\n  @leave=\"handleLeave\"\n  @after-leave=\"handleAfterLeave\"\n  @leave-cancelled=\"handleLeaveCancelled\"\n>\n  <slot name=\"default\" />\n</transition>", "legend": [{"cls": ".origam-transition--expand-y-enter-active", "num": 1, "descriptionKey": "components.expand_y.anatomy.enter_active", "descriptionFallback": "Enter phase. CSS class drives transition-duration (0.5s), timing (cubic-bezier(0.4,0,0.2,1)) and transition-property (height). The JS beforeEnter hook stashes the initial height; enter sets height to 0 then requestAnimationFrame restores offsetHeight."}, {"cls": ".origam-transition--expand-y-leave-active", "num": 2, "descriptionKey": "components.expand_y.anatomy.leave_active", "descriptionFallback": "Leave phase. CSS class drives transition-duration (0.5s) and property (height). The JS leave hook stashes the current height and animates to 0. afterLeave restores the initial style."}], "classes": [{"cls": "origam-transition--expand-y-enter-active", "descriptionKey": "components.expand_y.anatomy.enter_active", "descriptionFallback": "Applied during enter. Sets transition-property: height, duration 0.5s."}, {"cls": "origam-transition--expand-y-leave-active", "descriptionKey": "components.expand_y.anatomy.leave_active", "descriptionFallback": "Applied during leave. Sets transition-property: height, duration 0.5s."}, {"cls": "origam-transition