"}, {"name": "--origam-transition--expand-y-enter-leave---transition-property", "defaultValue": "height", "descriptionKey": "components.expand_y.css_vars.leave_property", "descriptionFallback": "CSS property animated on leave."}, {"name": "--origam-transition--expand-y-move---transition-duration", "defaultValue": "0.5s", "descriptionKey": "components.expand_y.css_vars.move_duration", "descriptionFallback": "Duration of the move animation in group transitions."}, {"name": "--origam-transition--expand-y-move---transition-property", "defaultValue": "transform", "descriptionKey": "components.expand_y.css_vars.move_property", "descriptionFallback": "CSS property animated during group moves."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.expand_y.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props."}], "playground": {"controls": [{"kind": "switch", "prop": "disabled", "labelKey": "components.expand_y.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "select", "prop": "mode", "options": [{"label": "(default)", "value": ""}, {"label": "TRANSITION_MODE.IN_OUT", "value": "TRANSITION_MODE.IN_OUT"}, {"label": "in-out", "value": "in-out"}, {"label": "TRANSITION_MODE.OUT_IN", "value": "TRANSITION_MODE.OUT_IN"}, {"label": "out-in", "value": "out-in"}, {"label": "TRANSITION_MODE.DEFAULT", "value": "TRANSITION_MODE.DEFAULT"}, {"label": "default", "value": "default"}], "labelKey": "components.expand_y.playground.mode", "defaultValue": "", "labelFallback": "Mode"}], "defaultSlotContent": "Content"}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
