nKey": "components.expansion_panel.a11y.key_activate", "actionFallback": "Toggles the panel expanded/collapsed when focus is on the header button."}, {"key": "Tab", "actionKey": "components.expansion_panel.a11y.key_tab", "actionFallback": "Moves focus to the next interactive element (next header or content)."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---raised)", "tokenPath": "--origam-expansion-panel---background", "descriptionKey": "components.expansion_panel.tokens.background", "descriptionFallback": "Panel background — raised surface."}, {"type": "dimension", "value": "var(--origam-radius---sm)", "tokenPath": "--origam-expansion-panel---border-radius", "descriptionKey": "components.expansion_panel.tokens.border_radius", "descriptionFallback": "Panel corner radius."}, {"type": "duration", "value": "var(--origam-motion__duration---slow)", "tokenPath": "--origam-expansion-panel---transition-duration", "descriptionKey": "components.expansion_panel.tokens.transition_duration", "descriptionFallback": "Transition duration for expand/collapse animations."}, {"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-expansion-panel---active-margin-top", "descriptionKey": "components.expansion_panel.tokens.active_margin_top", "descriptionFallback": "Margin above active panels (16px)."}, {"type": "dimension", "value": "48px", "tokenPath": "--origam-expansion-panel__header---min-height", "descriptionKey": "components.expansion_panel.tokens.header_min_height", "descriptionFallback": "Header minimum height at rest."}, {"type": "dimension", "value": "64px", "tokenPath": "--origam-expansion-panel__header---min-height-active", "descriptionKey": "components.expansion_panel.tokens.header_min_height_active", "descriptionFallback": "Header minimum height when panel is expanded."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=