)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"56\" cy=\"40\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"56\" y=\"44\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"56\" cy=\"104\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"56\" y=\"108\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n", "code": "<div class=\"origam-expansion-panel\">\n  <!-- shadow pseudo-element -->\n  <div class=\"origam-expansion-panel__shadow\" />\n\n  <!-- conditional loader -->\n  <div class=\"origam-expansion-panel__loader\"><!-- OrigamProgress --></div>\n\n  <!-- header (button) -->\n  <origam-expansion-panel-header\n    class=\"origam-expansion-panel__header\"\n    aria-expanded=\"false\"\n    aria-controls=\"expansion-panel-content-{id}\"\n  >\n    <slot name=\"prepend\" />\n    <slot name=\"title\" />\n    <!-- expand/collapse icon -->\n  </origam-expansion-panel-header>\n\n  <!-- content (region) -->\n  <origam-expansion-panel-content\n    class=\"origam-expansion-panel__content\"\n    role=\"region\"\n    aria-labelledby=\"expansion-panel-header-{id}\"\n  >\n    <slot name=\"default\" />\n  </origam-expansion-panel-content>\n</div>", "legend": [{"cls": ".origam-expansion-panel", "num": 1, "descriptionKey": "components.expansion_panel.anatomy.root", "descriptionFallback": "Root element. Flex container for shadow, header and content."}, {"cls": ".origam-expansion-panel__shadow", "num": 2, "descriptionKey": "components.expansion_panel.anatomy.shadow", "descriptionFallback": "Absolutely positioned shadow layer. Uses box-shadow token. z-index: -1 prevents clipping content."}, {"cls": ".origam-expansion-panel__header / origam-expansion-panel-header", "num": 3, "descriptionKey": "components.expansion_panel.anatomy.header", "descriptionFallback": "Rendered as a <button> with aria-expanded and aria-controls. Carries the overlay, wrapper, prepend, title, append and expand icon."}, {"cls": ".origam-expansion-panel__content / origam-expansion-panel-content", "num": 4, "descriptionKey": "components.expansion_panel.anatomy.content", "descriptionFallback": "Content region with role=\"region\" and aria-labelledby. Animated via OrigamExpandY transition. Hosts the default slot."}], "classes": [{"cls": "origam-expansion-panel", "descriptionKey": "components.expansion_panel.anatomy.root", "descriptionFallback": "Root element."}, {"cls": "origam-expansion-panel--active", "descriptionKey": "components.expansion_panel.anatomy.active", "descriptionFallback": "Applied when the panel is selected/expanded."}, {"cls": "origam-expansion-panel--disabled", "descriptionKey": "components.expansion_panel.anatomy.disabled", "descriptionFallback": "Applied when disabled. Dims the header via overlay opacity."}, {"cls": "origam-expansion-panel__shadow", "descriptionKey": "components.expansion_panel.anatomy.shadow", "descriptionFallback": "Absolute shadow layer. z-index: -1."}, {"cls": "origam-expansion-panel-header", "descriptionKey": "components.expansion_panel.anatomy.header_class", "descriptionFallback": "Header button root. Carries aria-expanded, aria-controls, ripple."}, {"cls": "origam-expansion-panel-header__wrapper", "descriptionKey": "components.expansion_panel.anatomy.header_wrapper", "descriptionFallback": "Inner flex row: prepend | title | append."}, {"cls": "origam-expansion-panel-content", "descriptionKey": "components.expansion_panel.anatomy.content_class", "descriptionFallback": "Content region. role=\"region\" with aria-labelledby referencing header ID."}, {"cls": "origam-expansion-panel-content__wrapper", "descriptionKey": "components.expansion_panel.anatomy.content_wrapper", "descriptionFallback": "Inner padding wrapper for the panel body content."}], "svgDesc": "Schematic of the ExpansionPanel component with 5 numbered internal parts.", "svgTitle": "Anatomy of OrigamExpansionPanel", "rootClass": "origam-expansion-panel", "figcaption": "Anatomy of <code>&lt;origam-expansion-panel&gt;</code> — 4 internal parts. The shadow ① is an absolutely-positioned sibling. Header ③ is a <code>&lt;button&gt;</code> with aria-expanded. Content ④ has <code>role=\"region\"</code> and <code>aria-labelledby</code> pointing to the header.", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-expansion-panel---border-radius", "defaultValue": "{radius.sm} (4px)", "descriptionKey": "components.expansion_panel.css_vars.border_radius", "descriptionFallback": "Panel corner radius. Reset to 0 on inner panels in accordion/flat mode."}, {"name": "--origam-expansion-panel---transition-duration", "defaultValue": "{motion.duration.slow} (0.3s)", "descriptionKey": "components.expansion_panel.css_vars.transition_duration", "descriptionFallback": "Transition duration for margin, radius and max-width changes on expand/collapse."}, {"name": "--origam-expansion-panel---active-margin-top", "defaultValue": "{space.4} (16px)", "descriptionKey": "components.expansion_panel.css_vars.active_margin_top", "descriptionFallback": "Margin applied above an active panel (and the panel following it) to visually separate it from siblings."}, {"name": "--origam-expansion-panel---divider-color", "defaultValue": "{color.border.subtle}", "descriptionKey": "components.expansion_panel.css_vars.divider_color", "descriptionFallback": "Colour of the ::after separator line between panels (non-accordion mode)."}, {"name": "--origam-expansion-panel---divider-opacity", "defaultValue": "0.12", "descriptionKey": "components.expansion_panel.css_vars.divider_opacity", "descriptionFallback": "Opacity of the ::after separator. Fades to 0 adjacent to active panels."}, {"name": "--origam-expansion-panel__shadow---box-shadow", "defaultValue": "{shadow.sm}", "descriptionKey": "components.expansion_panel.css_vars.shadow