rigam-expansion-panel-header--focusable", "descriptionKey": "components.expansion_panel_header.anatomy.focusable", "descriptionFallback": "Applied when focusable=true. Enhances overlay opacity when active and focused."}, {"cls": "origam-expansion-panel-header--static", "descriptionKey": "components.expansion_panel_header.anatomy.static", "descriptionFallback": "Applied when static=true. Header is rendered without toggle behaviour."}, {"cls": "origam-expansion-panel-header__overlay", "descriptionKey": "components.expansion_panel_header.anatomy.overlay", "descriptionFallback": "Absolutely positioned state overlay."}, {"cls": "origam-expansion-panel-header__wrapper", "descriptionKey": "components.expansion_panel_header.anatomy.wrapper", "descriptionFallback": "Inner flex row containing prepend, title and append."}, {"cls": "origam-expansion-panel-header__prepend", "descriptionKey": "components.expansion_panel_header.anatomy.prepend", "descriptionFallback": "Leading slot area."}, {"cls": "origam-expansion-panel-header__title", "descriptionKey": "components.expansion_panel_header.anatomy.title", "descriptionFallback": "Title text span."}, {"cls": "origam-expansion-panel-header__append", "descriptionKey": "components.expansion_panel_header.anatomy.append", "descriptionFallback": "Trailing slot area with expand/collapse icon."}], "svgDesc": "Schematic of the ExpansionPanelHeader component with 5 numbered internal parts.", "svgTitle": "Anatomy of OrigamExpansionPanelHeader", "rootClass": "origam-expansion-panel-header", "figcaption": "Anatomy of <code>&lt;origam-expansion-panel-header&gt;</code> — 5 internal parts. Root ① is rendered as a <code>&lt;button&gt;</code> with <code>aria-expanded</code> and <code>aria-controls</code>. The overlay ② covers the entire button for hover/focus state painting.", "svgViewBox": "0 0 700 180"}, "cssVars": [{"name": "--origam-expansion-panel__header---font-size", "defaultValue": "0.9375rem", "descriptionKey": "components.expansion_panel_he