ge"}, {"label": "ROUNDED.X_LARGE", "value": "ROUNDED.X_LARGE"}, {"label": "shaped", "value": "shaped"}, {"label": "ROUNDED.SHAPED", "value": "ROUNDED.SHAPED"}, {"label": "shaped-invert", "value": "shaped-invert"}, {"label": "ROUNDED.SHAPED_INVERT", "value": "ROUNDED.SHAPED_INVERT"}], "labelKey": "components.field.playground.rounded", "defaultValue": "", "labelFallback": "Rounded"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.field.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "flat", "labelKey": "components.field.playground.flat", "defaultValue": false, "labelFallback": "Flat"}], "defaultSlotContent": "Content"}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('587472e5-8bf5-452c-ae48-a01303ee312b', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'component', 'file-field', 'FileField', 'Form & Input', NULL, 'mdi-file-upload-outline', 'components.catalog.file_field.description', 'File upload input with three display modes (list, chips, counter), an optional drag-and-drop dropzone, file size validation, progress tracking and per-item download/remove actions.', NULL, NULL, 'origam-file-field', NULL, 'packages/ds/src/components/FileField/OrigamFileField.vue', 'origam', NULL, NULL, '/stories/?story=components-filefield--design', '/docs/components/FileField/OrigamFileField.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.file_field.a11y.label", "noteFallback": "The dropzone is a <label> element pointing to the hidden <input type=\"file\">. Clicking anywhere on the label opens the native file picker."}, {"noteKey": "components.file_field.a11y.drag_events", "noteFallback": "Drag events (dragenter, dragover, dragleave, drop) are handled on the <label>. The --dragging modifier class provides visual feedback during dragover."}, {"noteKey": "components.file_field.a11y.disabled", "noteFallback": "When disabled=true, the hidden input is disabled and cursor changes to not-allowed. The dropzone opacity drops to 0.6."}, {"noteKey": "components.file_field.a11y.error", "noteFallback": "When error is truthy, the dropzone border changes to the danger semantic colour. The error message (if a string) is displayed inside the dropzone area."}], "roles": [], "keyboard": [{"key": "Tab", "actionKey": "components.file_field.a11y.key_tab", "actionFallback": "Moves focus to the file input or dropzone label."}, {"key": "Enter / Space", "actionKey": "components.file_field.a11y.key_activate", "actionFallback": "Opens the native file picker when the dropzone label has focus."}]}, "tokens": {"excerpt": [{"type": "color", "value": "rgba(0, 0, 0, 0)", "tokenPath": "--origam-file-field__dropzone---background-color", "descriptionKey": "components.file_field.tokens.dropzone_bg", "descriptionFallback": "Default dropzone background."}, {"type": "color", "value": "var(--origam-color__border---default)", "tokenPath": "--origam-file-field__dropzone---color", "descriptionKey": "components.file_field.tokens.dropzone_color", "descriptionFallback": "Dropzone dashed border and text colour."}, {"type": "dimension", "value": "var(--origam-radius---md)", "tokenPath": "--origam-file-field__dropzone---border-radius", "descriptionKey": "components.file_field.tokens.dropzone_border_radius", "descriptionFallback": "Dropzone corner radius (8px)."}, {"type": "dimension", "value": "140px", "tokenPath": "--origam-file-field__dropzone---min-height", "descriptionKey": "components.file_field.tokens.dropzone_min_height", "descriptionFallback": "Minimum height of the empty dropzone."}, {"type": "color", "value": "var(--origam-color__feedback--info---bgSubtle)", "tokenPath": "--origam-file-field__dropzone--dragging---background-color", "descriptionKey": "components.file_field.tokens.dropzone_dragging_bg", "descriptionFallback": "Dropzone background during dragover."}, {"type": "color", "value": "var(--origam-color__feedback--danger---bg)", "tokenPath": "--origam-file-field__dropzone--error---border-color", "descriptionKey": "components.file_field.tokens.dropzone_error_border", "descriptionFallback": "Dropzone border in error state."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"220\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"16\" width=\"644\" height=\"100\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"70\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">OrigamInput → OrigamField (label, prepend/append, clearable)</text>\n  <rect x=\"48\" y=\"128\" width=\"604\" height=\"76\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"170\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__dragndrop / file list (display mode: list | chips | counter)</text>\n  <circle cx=\"36\" cy=\"24\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"28.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"56\" cy=\"136\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"56\" y=\"140\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n", "code": "<origam-input class=\"origam-file-field\">\n  <!-- OrigamField handles label, prepend/append inner, clearable -->\n\n  <!-- hidden native file input -->\n  <input type=\"file\" :multiple=\"multiple\" style=\"opacity:0;position:absolute;\" />\n\n  <!-- dropzone mode -->\n  <div v-if=\"isDropzoneMode\" class=\"origam-file-field__dragndrop\">\n    <label class=\"origam-file-field__dropzone\">\n      <!-- icon + title + subtitle / single-file DnD item -->\n      <origam-file-field-drag-n-drop-item v-if=\"!multiple && hasFiles\" />\n      <template v-else>\n        <origam-icon class=\"origam-file-field__dropzone-icon\" />\n        <div class=\"origam-file-field__dropzone-title\" />\n        <div class=\"origam-file-field__dropzone-subtitle\" />\n      </template>\n    </label>\n\n    <!-- multi-file list below dropzone -->\n    <div v-if=\"multiple && hasFiles\" class=\"origam-file-field__list\">\n      <origam-file-field-list-item v-for=\"(file, i) in model\" :key=\"i\" />\n    </div>\n  </div>\n</origam-input>", "legend": [{"cls": ".origam-file-field", "num": 1, "descriptionKey": "components.file_field.anatomy.root", "descriptionFallback": "Root element. Extends OrigamInput which itself renders an OrigamField with label, prepend/append zones, and clearable."}, {"cls": ".origam-file-field__dragndrop", "num": 2, "descriptionKey": "components.file_field.anatomy.dragndrop", "descriptionFallback": "Drag-and-drop wrapper rendered when dropzone/dragndrop=true. Houses the <label> dropzone area and the file list below it."}, {"cls": ".origam-file-field__dropzone", "num": 3, "descriptionKey": "components.file_field.anatomy.dropzone", "descriptionFallback": "<label> element acting as the drop target. Accepts drag events, triggers the hidden file input on click. Has --dragging modifier on dragover."}, {"cls": ".origam-file-field__list", "num": 4, "descriptionKey": "components.file_field.anatomy.list", "descriptionFallback": "Vertical list of OrigamFileFieldListItem cards shown below the field in list display mode."}, {"cls": ".origam-file-field__dropzone-icon / __dropzone-title / __dropzone-subtitle", "num": 5, "descriptionKey": "components.file_field.anatomy.dropzone_content", "descriptionFallback": "Inner dropzone content zones: upload icon, primary title text, and secondary subtitle text."}], "classes": [{"cls": "origam-file-field", "descriptionKey": "components.file_field.anatomy.root", "descriptionFallback": "Root element wrapping OrigamInput."}, {"cls": "origam-file-field__dragndrop", "descriptionKey": "components.file_field.anatomy.dragndrop", "descriptionFallback": "Drag-and-drop container (dropzone + list below)."}, {"cls": "origam-file-field__dropzone", "descriptionKey": "components.file_field.anatomy.dropzone", "descriptionFallback": "<label> drop target. Adds --dragging modifier on dragover."}, {"cls": "origam-file-field__dropzone-icon", "descriptionKey": "components.file_field.anatomy.dropzone_icon", "descriptionFallback": "Upload icon glyph inside the dropzone."}, {"cls": "origam-file-field__dropzone-title", "descriptionKey": "components.file_field.anatomy.dropzone_title", "descriptionFallback": "Primary text area inside the dropzone."}, {"cls": "origam-file-field__dropzone-subtitle", "descriptionKey": "components.file_field.anatomy.dropzone_subtitle", "descriptionFallback": "Secondary text area inside the dropzone."}, {"cls": "origam-file-field__list", "descriptionKey": "components.file_field.anatomy.list", "descriptionFallback": "Vertical file card list below the field (list display mode)."}], "svgDesc": "Schematic of the FileField component with 5 numbered internal parts.", "svgTitle": "Anatomy of OrigamFileField", "rootClass": "origam-file-field", "figcaption": "Anatomy of <code>&lt;origam-file-field&gt;</code>. The root ① extends OrigamInput → OrigamField (label, icons, clearable). Below the field ②, the display zone renders in one of three modes: list (card stack), chips (closable chips row), or counter (\"{n} files\").", "svgViewBox": "0 0 700 220"}, "cssVars": [{"name": "--origam-file-field---gap", "defaultValue": "{space.2} (8px)", "descriptionKey": "components.file_field.css_vars.gap", "descriptionFallback": "Gap between the dropzone wrapper sections (dropzone + list)."}, {"name": "--origam-file-field---list-gap", "defaultValue": "{space.2} (8px)", "descriptionKey": "components.file_field.css_vars.list_gap", "descriptionFallback": "Gap between file-field list items."}, {"name": "--origam-file-field__dropzone---background-color", "defaultValue": "transparent", "descriptionKey": "components.file_field.css_vars.dropzone_background_color", "descriptionFallback": "Default dropzone background colour."}, {"name": "--origam-file-field__dropzone---color", "defaultValue": "{color.border.default}", "descriptionKey": "components.file_field.css_vars.dropzone_color", "descriptionFallback": "Dropzone dashed border colour and text colour fallback."}, {"name": "--origam-file-field__dropzone---border-radius", "defaultValue": "{radius.md} (8px)", "descriptionKey": "components.file_field.css_vars.dropzone_border_radius", "descriptionFallback": "Dropzone corner radius."}, {"name": "--origam-file-field__dropzone---min-height", "defaultValue": "140px", "descriptionKey": "components.file_field.css_vars.dropzone_min_height", "descriptionFallback": "Minimum height of the empty dropzone area."}, {"name": "--origam-file-field__dropzone--dragging---background-color", "defaultValue": "{color.feedback.info.bgSubtle}", "descriptionKey": "components.file_field.css_vars.dropzone_dragging_bg", "descriptionFallback": "Dropzone background during dragover."}, {"name": "--origam-file-field__dropzone--dragging---border-color", "defaultValue": "{color.feedback.info.bg}", "descriptionKey": "components.file_field.css_vars.dropzone_dragging_border", "descriptionFallback": "Dropzone border colour during dragover."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.file_field.exposed.filter_props", "descriptionFallback": "Filters and forwards a subset of props."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.file_field.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.file_field.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.file_field.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.file_field.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.file_field.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "text", "prop": "label", "labelKey": "components.file_field.playground.label", "defaultValue": "Upload a file", "labelFallback": "Label"}, {"kind": "select", "prop": "variant", "options": [{"label": "outlined", "value": "outlined"}, {"label": "underlined", "value": "underlined"}, {"label": "filled", "value": "filled"}, {"label": "solo", "value": "solo"}], "labelKey": "components.file_field.playground.variant", "defaultValue": "outlined", "labelFallback": "Variant"}, {"kind": "switch", "prop": "multiple", "labelKey": "components.file_field.playground.multiple", "defaultValue": false, "labelFallback": "Multiple"}, {"kind": "switch", "prop": "dropzone", "labelKey": "components.file_field.playground.dropzone", "defaultValue": false, "labelFallback": "Dropzone mode"}, {"kind": "switch", "prop": "chips", "labelKey": "components.file_field.playground.chips", "defaultValue": false, "labelFallback": "Chips display"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.file_field.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}]}, "previewVariants": [{"label": "default", "props": {"label": "Upload a file", "variant": "outlined"}}, {"label": "dropzone", "props": {"label": "Drop files", "dropzone": true, "multiple": true}}, {"label": "chips", "props": {"chips": true, "label": "Attachments", "multiple": true}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('c8605793-13e0-46f7-b6d6-4542049285ee', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'component', 'file-field-drag-n-drop-item', 'FileFieldDragNDropItem', 'Form & Input', NULL, 'mdi-file-upload-outline', 'components.catalog.file_field_drag_n_drop_item.description', 'File card rendered inside a drag-and-drop dropzone. Displays the file icon, name, human-readable size, an optional progress bar, and a remove button.', NULL, NULL, 'origam-file-field-drag-n-drop-item', NULL, 'packages/ds/src/components/FileField/OrigamFileFieldDragNDropItem.vue', 'origam', NULL, NULL, '/stories/?story=components-filefield--design', '/docs/components/FileField/OrigamFileField.html', 'file-field', '{"a11y": {"notes": [{"noteKey": "components.file_field_drag_n_drop_item.a11y.remove_btn", "noteFallback": "The remove button is a native <button> (via OrigamBtn). It is disabled when disabled=true or readonly=true — pointer events and keyboard activation are suppressed."}], "roles": [], "keyboard": [{"key": "Enter / Space", "actionKey": "components.file_field_drag_n_drop_item.a11y.key_remove", "actionFallback": "Activates the remove button when focused — native <button> behaviour."}, {"key": "Tab", "actionKey": "components.file_field_drag_n_drop_item.a11y.key_tab", "actionFallback": "Moves focus to the remove button and then to the next interactive element."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-space---3)", "tokenPath": "--origam-file-field-dragndrop-item---gap", "descriptionKey": "components.file_field_drag_n_drop_item.tokens.gap", "descriptionFallba