origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"78\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">grid-column / grid-row / grid-area</text>\n  <rect x=\"60\" y=\"90\" width=\"580\" height=\"48\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"119\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#default slot</text>\n  <circle cx=\"36\" cy=\"48\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"52.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"68\" cy=\"98\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"68\" y=\"102.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <line x1=\"46\" y1=\"44\" x2=\"88\" y2=\"28\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"92\" y=\"28\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-grid-item</text>\n", "legend": [{"cls": ".origam-grid-item", "num": 1, "descriptionKey": "components.grid_item.anatomy.root", "descriptionFallback": "Root element. Sets <code>grid-column</code>, <code>grid-row</code> or <code>grid-area</code> via inline styles. Also applies <code>min-width: 0; min-height: 0</code> to prevent overflow."}, {"cls": ".origam-grid-item #default", "num": 2, "descriptionKey": "components.grid_item.anatomy.slot", "descriptionFallback": "Default slot hosting the cell content. No constraints imposed — content defines its own sizing."}], "svgDesc": "Schematic of the GridItem component with 2 numbered internal parts.", "svgTitle": "Anatomy of OrigamGridItem", "rootClass": "origam-grid-item", "figcaption": "Anatomy of <code>&lt;origam-grid-item&gt;</code> — 2 parts: the root element carrying grid placement styles, and the default slot hosting the cell content.", "svgViewBox": "0 0 700 200"}, "cssVars": [], "exposed": [{"name": "columnCss", "type": "ComputedRef<string | undefined>", "descriptionKey": "components.grid_item.exposed.column_css", "descriptionFallback": "Serialised grid-column value derived from the column prop. Readable by parent tooling."}, {"name": "rowCss", "type": "ComputedRef<string | undefined>", "descriptionKey": "components.grid_item.exposed.row_css", "descriptionFallback": "Serialised grid-row value derived from the row prop."}], "playground": {"controls": [{"kind": "select", "prop": "alignSelf", "options": [{"label": "(default)", "value": ""}, {"label": "start", "value": "start"}, {"label": "center", "value": "center"}, {"label": "end", "value": "end"}, {"label": "stretch", "value": "stretch"}], "labelKey": "components.grid_item.playground.align_self", "defaultValue": "", "labelFallback": "Align Self"}, {"kind": "select", "prop": "justifySelf", "options": [{"label": "(default)", "value": ""}, {"label": "start", "value": "start"}, {"label": "center", "value": "center"}, {"label": "end", "value": "end"}, {"label": "stretch", "value": "stretch"}], "labelKey": "components.grid_item.playground.justify_self", "defaultValue": "", "labelFallback": "Justify Self"}], "defaultSlotContent": "Content"}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('e8e7b477-0039-455a-a748-8164da9a5d1e', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'component', 'icon', 'Icon', 'Media', NULL, 'mdi-star-four-points', 'components.catalog.icon.description', 'Universal icon renderer that adapts to MDI class icons, SVG paths, component-based icons and Unicode ligatures.', NULL, NULL, 'origam-icon', NULL, 'packages/ds/src/components/Icon/OrigamIcon.vue', 'origam', NULL, NULL, '/stories/?story=components-icon--design', '/docs/components/Icon/OrigamIcon.html', NULL, '{"playground": {"controls": [{"kind": "switch", "prop": "disabled", "labelKey": "components.icon.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}], "defaultSlotContent": "Content"}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('6c1c29d8-8316-40d9-afd3-e02f02855f14', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'component', 'img', 'Img', 'Data Display', NULL, 'mdi-image-outline', 'components.catalog.img.description', 'Responsive image component with lazy loading, aspect-ratio enforcement, placeholder and error slot, optional gradient overlay, srcset / sizes support, and a smooth fade-in transition on load.', NULL, NULL, 'origam-img', NULL, 'packages/ds/src/components/Img/OrigamImg.vue', 'origam', NULL, NULL, '/stories/?story=components-img--design', '/docs/components/Img/OrigamImg.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.img.a11y.alt", "noteFallback": "Always provide a meaningful alt text. When alt is present, role=\"img\" and aria-label={alt} are set on the root. For decorative images, omit alt and set aria-hidden=\"true\" on the parent."}, {"noteKey": "components.img.a11y.lazy_loading", "noteFallback": "Lazy loading is handled via IntersectionObserver (not the native loading=\"lazy\" attribute) so the component loads the image only when it enters the viewport. The placeholder slot is announced by the browser as the alt text is still present on the root."}, {"noteKey": "components.img.a11y.error_slot", "noteFallback": "When the image fails to load, the #error slot is shown. The slot content should include meaningful text or an icon-with-label so users know the image did not load."}, {"noteKey": "components.img.a11y.reduced_motion", "noteFallback": "The fade-in transition respects prefers-reduced-motion. When the user prefers reduced motion, set transition=\"false\" or use --origam-img---transition-duration: 0ms."}], "roles": ["img"], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"16\" width=\"644\" height=\"168\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"48\" y=\"36\" width=\"604\" height=\"108\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"350\" y=\"80\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__picture (absolute, object-fit: contain/cover)</text>\n  <rect x=\"200\" y=\"52\" width=\"300\" height=\"40\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"350\" y=\"76\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">__placeholder (lazy load blur)</text>\n  <rect x=\"48\" y=\"156\" width=\"604\" height=\"20\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.15))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"350\" y=\"170\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">#default slot (overlay content)</text>\n  <circle cx=\"36\" cy=\"24\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"28.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"56\" cy=\"44\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"56\" y=\"48\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"200\" cy=\"56\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"200\" y=\"60\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<!-- OrigamImg — wraps OrigamResponsive for aspect ratio -->\n<origam-responsive\n  v-intersect=\"intersect\"\n  :aria-label=\"alt\"\n  :aspect-ratio=\"aspectRatio\"\n  :role=\"alt ? ''img'' : undefined\"\n  class=\"origam-img\"\n>\n  <template #additional>\n    <!-- main image (fade-in on load) -->\n    <origam-transition :transition=\"transition\">\n      <img v-show=\"isLoaded\" class=\"origam-img__picture origam-img__picture--cover\" />\n    </origam-transition>\n\n    <!-- lazySrc placeholder (blur filter) -->\n    <origam-transition :transition=\"transition\">\n      <img v-if=\"lazySrc && !isLoaded\" class=\"origam-img__picture origam-img__picture--preload\" />\n    </origam-transition>\n\n    <!-- #placeholder slot — v-if isLoading && slots.placeholder -->\n    <div v-if=\"(isLoading || isError) && slots.placeholder\" class=\"origam-img__placeholder\">\n      <slot name=\"placeholder\" />\n    </div>\n\n    <!-- #error slot — v-if isError && slots.error -->\n    <div v-if=\"isError && slots.error\" class=\"origam-img__error\">\n      <slot name=\"error\" />\n    </div>\n\n    <!-- gradient overlay — v-if gradient -->\n    <div v-if=\"gradient\" class=\"origam-img__gradient\" />\n  </template>\n\n  <!-- #default slot — overlay content -->\n  <template #default v-if=\"hasContent\">\n    <slot name=\"default\" />\n  </template>\n</origam-responsive>", "legend": [{"cls": ".origam-img", "num": 1, "descriptionKey": "components.img.anatomy.root", "descriptionFallback": "Root element wrapping OrigamResponsive. Carries role=\"img\" when alt is present. Has --booting modifier until aspectRatio resolves."}, {"cls": ".origam-img__picture", "num": 2, "descriptionKey": "components.img.anatomy.picture", "descriptionFallback": "Native <img> element. Absolutely positioned, 100% width/height. Has --cover (object-fit: cover) or --contain (object-fit: contain) modifier. Has --preload modifier with blur filter when showing lazySrc."}, {"cls": ".origam-img__placeholder", "num": 3, "descriptionKey": "components.img.anatomy.placeholder", "descriptionFallback": "Shown during loading (or lazySrc phase) when the #placeholder slot is provided. Absolutely positioned layer behind the main image."}, {"cls": ".origam-img__error", "num": 4, "descriptionKey": "components.img.anatomy.error", "descriptionFallback": "Shown when the image fails to load and the #error slot is provided."}, {"cls": ".origam-img__gradient", "num": 5, "descriptionKey": "components.img.anatomy.gradient", "descriptionFallback": "Absolutely positioned <div> rendered when gradient prop is set. Applies background-image: linear-gradient(...)."}], "classes": [{"cls": "origam-img", "descriptionKey": "components.img.anatomy.root", "descriptionFallback": "Root element. Has --booting class until aspectRatio resolves (prevents premature paint)."}, {"cls": "origam-img--booting", "descriptionKey": "components.img.anatomy.booting", "descriptionFallback": "Disables the sizer transition during initial mount. Removed after first rAF."}, {"cls": "origam-img__picture", "descriptionKey": "components.img.anatomy.picture", "descriptionFallback": "Native <img>. Always absolutely positioned inside the responsive sizer."}, {"cls": "origam-img__picture--cover", "descriptionKey": "components.img.anatomy.picture_cover", "descriptionFallback": "object-fit: cover — image fills the container, cropped."}, {"cls": "origam-img__picture--contain", "descriptionKey": "components.img.anatomy.picture_contain", "descriptionFallback": "object-fit: contain — image fits inside the container without cropping."}, {"cls": "origam-img__picture--preload", "descriptionKey": "components.img.anatomy.picture_preload", "descriptionFallback": "Applied to the lazySrc image. Has blur filter while the full-res image loads."}, {"cls": "origam-img__placeholder", "descriptionKey": "components.img.anatomy.placeholder", "descriptionFallback": "#placeholder slot wrapper. Shown during loading."}, {"cls": "origam-img__error", "descriptionKey": "components.img.anatomy.error", "descriptionFallback": "#error slot wrapper. Shown on load failure."}, {"cls": "origam-img__gradient", "descriptionKey": "components.img.anatomy.gradient", "descriptionFallback": "Gradient overlay div. background-image set from the gradient prop."}], "svgDesc": "Schematic of the Img component with 5 numbered internal parts.", "svgTitle": "Anatomy of OrigamImg", "rootClass": "origam-img", "figcaption": "Anatomy of <code>&lt;origam-img&gt;</code> — 5 internal parts. The root ① wraps OrigamResponsive for aspect-ratio enforcement. The picture ② is absolutely positioned. Placeholder ③ and error ④ layers are conditional. The gradient ⑤ is an absolute div when the gradient prop is set.", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-img---background-color", "defaultValue": "{color.surface.overlay}", "descriptionKey": "components.img.css_vars.background_color", "descriptionFallback": "Background colour of the image container while the image loads."}, {"name": "--origam-img---border-radius", "defaultValue": "{radius.none} (0px)", "descriptionKey": "components.img.css_vars.border_radius", "descriptionFallback": "Corner radius of the image root. Overridden by the rounded prop."}, {"name": "--origam-img---transition-duration", "defaultValue": "{motion.duration.medium}", "descriptionKey": "components.img.css_vars.transition_duration", "descriptionFallback": "Fade-in transition duration when the image loads."}, {"name": "--origam-img__picture--preload---filter", "defaultValue": "blur(4px)", "descriptionKey": "components.img.css_vars.picture_preload_filter", "descriptionFallback": "CSS filter applied to the lazySrc placeholder image."}, {"name": "--origam-img__picture--contain---object-fit", "defaultValue": "contain", "descriptionKey": "components.img.css_vars.picture_contain_object_fit", "descriptionFallback": "object-fit value for the --contain modifier."}, {"name": "--origam-img__picture--cover---object-fit", "defaultValue": "cover", "descriptionKey": "components.img.css_vars.picture_cover_object_fit", "descriptionFallback": "object-fit value for the --cover modifier."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.img.exposed.filter_props", "descriptionFallback": "Filters and forwards a subset of props."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.img.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.img.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.img.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.img.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "ComputedRef<boolean>", "descriptionKey": "components.img.exposed.is_loaded", "descriptionFallback": "True when the image has successfully loaded (state === LOADED)."}, {"name": "styleIsLoaded", "type": "Ref<boolean>", "descriptionKey": "components.img.exposed.style_is_loaded", "descriptionFallback": "True once the component style sheet has been injected. Note: distinct from isLoaded (image load state)."}], "playground": {"controls": [{"kind": "text", "prop": "src", "labelKey": "components.img.playground.src", "defaultValue": "https://picsum.photos/600/400", "labelFallback": "Source URL"}, {"kind": "text", "prop": "alt", "labelKey": "components.img.playground.alt", "defaultValue": "Landscape photo", "labelFallback": "Alt text"}, {"kind": "switch", "prop": "cover", "labelKey": "components.img.playground.cover", "defaultValue": false, "labelFallback": "Cover (vs contain)"}, {"kind": "select", "prop": "aspectRatio", "options": [{"label": "(auto)", "value": ""}, {"label": "16/9", "value": "1.7778"}, {"label": "4/3", "value": "1.3333"}, {"label": "1/1 (square)", "value": "1"}, {"label": "3/4 (portrait)", "value": "0.75"}], "labelKey": "components.img.playground.aspect_ratio", "defaultValue": "", "labelFallback": "Aspect ratio"}, {"kind": "select", "prop": "rounded", "options": [{"label": "(none)", "value": ""}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}, {"label": "xl", "value": "xl"}, {"label": "pill", "value": "pill"}], "labelKey": "components.img.playground.rounded", "defaultValue": "", "labelFallback": "Rounded"}, {"kind": "select", "prop": "gradient", "options": [{"label": "(none)", "value": ""}, {"label": "to bottom (dark)", "value": "to bottom, transparent, rgba(0,0,0,0.6)"}, {"label": "to top (dark)", "value": "to top, transparent, rgba(0,0,0,0.6)"}], "labelKey": "components.img.playground.gradient", "defaultValue": "", "labelFallback": "Gradient"}]}, "previewVariants": [{"label": "contain", "props": {"alt": "Photo (contain)", "src": "https://picsum.photos/400/300", "width": 200, "aspectRatio": "4/3"}}, {"label": "cover", "props": {"alt": "Photo (cover)", "src": "https://picsum.photos/400/300", "cover": true, "width": 200, "aspectRatio": "4/3"}}, {"label": "rounded", "props": {"alt": "Rounded photo", "src": "https://picsum.photos/300/300", "cover": true, "width": 120, "rounded": "xl", "aspectRatio": 1}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('72959551-6168-4620-952c-887fca5e2348', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'component', 'infinite-scroll', 'InfiniteScroll', 'Data Display', NULL, 'mdi-infinity', 'components.catalog.infinite_scroll.description', 'Sentinel-based infinite scroll that fires a load event when the user reaches the start or end of a scrollable area.', NULL, NULL, 'origam-infinite-scroll', NULL, 'packages/ds/src/components/InfiniteScroll/OrigamInfiniteScroll.vue', 'origam', NULL, NULL, '/stories/?story=components-infinite-scroll--design', '/docs/components/InfiniteScroll/OrigamInfiniteScroll.html', NULL, '{"playground": {"controls": [{"kind": "select", "prop": "side", "options": [{"label": "(default)", "value": ""}, {"label": "start", "value": "start"}, {"label": "end", "value": "end"}, {"label": "both", "value": "both"}], "labelKey": "components.infinite_scroll.playground.side", "defaultValue": "", "labelFallback": "Side"}, {"kind": "select", "prop": "mode", "options": [{"label": "(default)", "value": ""}, {"label": "intersect", "value": "intersect"}, {"label": "manual", "value": "manual"}], "labelKey": "components.infinite_scroll.playground.mode", "defaultValue": "", "labelFallback": "Mode"}, {"kind": "select", "prop": "direction", "options": [{"label": "(default)", "value": ""}, {"label": "horizontal", "value": "horizontal"}, {"label": "vertical", "value": "vertical"}], "labelKey": "components.infinite_scroll.playground.direction", "defaultValue": "", "labelFallback": "Direction"}], "defaultSlotContent": "Content"}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('324f22f5-bfbe-4adf-9bfe-de43c962ec09', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'component', 'infinite-scroll-intersect', 'InfiniteScrollIntersect', 'Data Display', NULL, 'mdi-arrow-collapse-down', 'components.catalog.infinite_scroll_intersect.description', 'Low-level sentinel element used by InfiniteScroll to detect when the scroll boundary enters the viewport via IntersectionObserver.', NULL, NULL, 'origam-infinite-scroll-intersect', NULL, 'packages/ds/src/components/InfiniteScroll/OrigamInfiniteScrollIntersect.vue', 'origam', NULL, NULL, '/stories/?story=components-infinite-scroll--design', '/docs/components/InfiniteScroll/OrigamInfiniteScroll.html', 'infinite-scroll', '{"a11y": {"notes": [{"noteKey": "components.infinite_scroll_intersect.a11y.invisible_note", "noteFallback": "The sentinel is a non-interactive, invisible element with no ARIA role. Screen readers ignore it. Announce newly loaded content via a live region on the parent component."}], "roles": [], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-infinite-scroll__loader---color", "descriptionKey": "components.infinite_scroll_intersect.tokens.loader_color", "descriptionFallback": "Color passed to the OrigamProgress spinner in the loading slot."}, {"type": "dimension", "value": "var(--origam-space---3)", "tokenPath": "--origam-infinite-scroll__loader---gap", "descriptionKey": "components.infinite_scroll_intersect.tokens.loader_gap", "descriptionFallback": "Gap between loader and adjacent elements within the side zone."}, {"type": "color", "value": "var(--origam-color__text---secondary)", "tokenPath": "--origam-infinite-scroll__empty---color", "descriptionKey": "components.infinite_scroll_intersect.tokens.empty_color", "descriptionFallback": "Text color for the empty-state message shown when no more items are available."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"160\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"40\" width=\"644\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"6 3\"/>\n  <text x=\"350\" y=\"84\" font-size=\"10\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">height: 1px (invisible sentinel)</text>\n  <circle cx=\"36\" cy=\"48\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"52.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <line x1=\"46\" y1=\"44\" x2=\"88\" y2=\"28\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"92\" y=\"28\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-infinite-scroll-intersect</text>\n", "legend": [{"cls": ".origam-infinite-scroll-intersect", "num": 1, "descriptionKey": "components.infinite_scroll_intersect.anatomy.root", "descriptionFallback": "Root element. A minimal <code>&lt;div&gt;</code> containing a non-breaking space (<code>&amp;nbsp;</code>) to ensure the browser paints it. Observed by <code>useIntersectionObserver</code> and fires the <code>intersect</code> emit on visibility change."}], "svgDesc": "Schematic of the InfiniteScrollIntersect sentinel element with 1 numbered part.", "svgTitle": "Anatomy of OrigamInfiniteScrollIntersect", "rootClass": "origam-infinite-scroll-intersect", "figcaption": "Anatomy of <code>&lt;origam-infinite-scroll-intersect&gt;</code> — a single invisible sentinel <code>&lt;div&gt;</code> observed by an IntersectionObserver.", "svgViewBox": "0 0 700 160"}, "cssVars": [{"name": "--origam-infinite-scroll---loader-color", "defaultValue": "{color.action.primary.bg}", "descriptionKey": "components.infinite_scroll_intersect.css_vars.loader_color", "descriptionFallback": "Color of the loading spinner in the parent InfiniteScroll loader slot."}, {"name": "--origam-infinite-scroll---loader-gap", "defaultValue": "{space.3}", "descriptionKey": "components.infinite_scroll_intersect.css_vars.loader_gap", "descriptionFallback": "Gap between the loader and adjacent elements in the side zone."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.infinite_scroll_intersect.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}], "playground": {"controls": [{"kind": "select", "prop": "side", "options": [{"label": "(default)", "value": ""}, {"label": "start", "value": "start"}, {"label": "INFINITE_SCROLL_SIDE.START", "value": "INFINITE_SCROLL_SIDE.START"}, {"label": "INFINITE_SCROLL_SIDE.END", "value": "INFINITE_SCROLL_SIDE.END"}, {"label": "end", "value": "end"}, {"label": "INFINITE_SCROLL_SIDE.BOTH", "value": "INFINITE_SCROLL_SIDE.BOTH"}, {"label": "both", "value": "both"}], "labelKey": "components.infinite_scroll_intersect.playground.side", "defaultValue": "", "labelFallback": "Side"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('6418043b-8b81-47cf-995c-10d1a200f69c', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'component', 'list-subheader', 'ListSubheader', 'Data Display', NULL, 'mdi-format-list-group', 'components.catalog.list_subheader.description', 'Section heading rendered inside a List. Supports inset indent and sticky positioning.', NULL, NULL, 'origam-list-subheader', NULL, 'packages/ds/src/components/List/OrigamListSubheader.vue', 'origam', NULL, NULL, '/stories/?story=components-list-subheader--design', '/docs/components/List/OrigamListSubheader.html', 'list', '{"a11y": {"notes": [{"noteKey": "components.list_subheader.a11y.semantic_note", "noteFallback": "For screen-reader accessibility, consider using tag=\"h2\" through \"h6\" so the subheader is part of the heading outline. The default <div> tag is appropriate when the list is not a standalone section."}, {"noteKey": "components.list_subheader.a11y.sticky_note", "noteFallback": "The sticky variant uses position: sticky; top: 0 — the parent list must have overflow: auto or overflow: scroll for this to work correctly."}, {"noteKey": "components.list_subheader.a11y.contrast_note", "noteFallback": "The default secondary text color may have reduced contrast. Ensure at least 4.5:1 contrast ratio when customising the color prop."}], "roles": [], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__text---secondary)", "tokenPath": "--origam-list-subheader---color", "descriptionKey": "components.list_subheader.tokens.color", "descriptionFallback": "Default text color (secondary)."}, {"type": "dimension", "value": "var(--origam-font__size---md)", "tokenPath": "--origam-list__subheader---font-size", "descriptionKey": "components.list_subheader.tokens.font_size", "descriptionFallback": "Font size (0.875rem)."}, {"type": "dimension", "value": "40px", "tokenPath": "--origam-list-subheader---min-height", "descriptionKey": "components.list_subheader.tokens.min_height", "descriptionFallback": "Minimum row height."}, {"type": "dimension", "value": "32px", "tokenPath": "--origam-list-subheader---inset-indent-padding", "descriptionKey": "components.list_subheader.tokens.inset_indent_padding", "descriptionFallback": "Indent applied in --inset mode to align with prepend icon items."}, {"type": "duration", "value": "var(--origam-motion__duration---medium)", "tokenPath": "--origam-list-subheader---transition-duration", "descriptionKey": "components.list_subheader.tokens.transition_duration", "descriptionFallback": "Transition duration for min-height changes."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"140\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"30\" width=\"660\" height=\"50\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"20\" y=\"30\" width=\"660\" height=\"50\" rx=\"4\" fill=\"none\" stroke=\"var(--origam-color__action--primary---bg, #a855f7)\" stroke-width=\"1\" stroke-dasharray=\"6 3\" opacity=\"0.6\"/>\n  <rect x=\"32\" y=\"44\" width=\"400\" height=\"22\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\"/>\n  <text x=\"232\" y=\"59\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__text (label)</text>\n  <circle cx=\"28\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"42\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"60\" cy=\"44\" r=\"8\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"60\" y=\"48\" font-size=\"8\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <line x1=\"38\" y1=\"36\" x2=\"90\" y2=\"20\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"94\" y=\"22\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-list-subheader</text>\n  <text x=\"350\" y=\"125\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">--inset adds 32px indent-padding · --sticky sets position: sticky top: 0</text>\n", "legend": [{"cls": ".origam-list-subheader", "num": 1, "descriptionKey": "components.list_subheader.anatomy.root", "descriptionFallback": "Root element. Flex container (align-items: center). Renders as <code>&lt;div&gt;</code> by default; use <code>tag=\"h2\"</code>–<code>\"h6\"</code> for semantic sectioning."}, {"cls": ".origam-list-subheader__text", "num": 2, "descriptionKey": "components.list_subheader.anatomy.text", "descriptionFallback": "Label text wrapper. <code>overflow: hidden; text-overflow: ellipsis; white-space: nowrap</code>. Rendered only when the title prop or default slot is provided."}], "svgDesc": "Schematic of the ListSubheader component with 2 numbered internal parts.", "svgTitle": "Anatomy of OrigamListSubheader", "rootClass": "origam-list-subheader", "figcaption": "Anatomy of <code>&lt;origam-list-subheader&gt;</code> — 2 internal parts. The root ① is a flex container; the inner text element ② truncates with ellipsis.", "svgViewBox": "0 0 700 140"}, "cssVars": [{"name": "--origam-list-subheader---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.list_subheader.css_vars.color", "descriptionFallback": "Text color of the subheader label. Defaults to the semantic secondary text color."}, {"name": "--origam-list-subheader---font-size", "defaultValue": "0.875rem", "descriptionKey": "components.list_subheader.css_vars.font_size", "descriptionFallback": "Font size of the subheader label."}, {"name": "--origam-list-subheader---font-weight", "defaultValue": "400", "descriptionKey": "components.list_subheader.css_vars.font_weight", "descriptionFallback": "Font weight of the subheader label."}, {"name": "--origam-list-subheader---min-height", "defaultValue": "40px", "descriptionKey": "components.list_subheader.css_vars.min_height", "descriptionFallback": "Minimum height of the subheader row. Transitions with density changes."}, {"name": "--origam-list-subheader---padding-inline-end", "defaultValue": "16px", "descriptionKey": "components.list_subheader.css_vars.padding_inline_end", "descriptionFallback": "Trailing padding to avoid text running to the edge."}, {"name": "--origam-list-subheader---line-height", "defaultValue": "1.375rem", "descriptionKey": "components.list_subheader.css_vars.line_height", "descriptionFallback": "Line height of the subheader text."}, {"name": "--origam-list-subheader---inset-indent-padding", "defaultValue": "32px", "descriptionKey": "components.list_subheader.css_vars.inset_indent_padding", "descriptionFallback": "Indent padding applied when --inset modifier is active. Aligns the label with prepend icons."}, {"name": "--origam-list-subheader---transition-duration", "defaultValue": "0.2s", "descriptionKey": "components.list_subheader.css_vars.transition_duration", "descriptionFallback": "Duration of the min-height transition."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.list_subheader.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.list_subheader.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed listSubheaderStyles."}, {"name": "id", "type": "string", "descriptionKey": "components.list_subheader.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.list_subheader.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.list_subheader.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.list_subheader.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "text", "prop": "title", "labelKey": "components.list_subheader.playground.title", "defaultValue": "Section header", "labelFallback": "Title"}, {"kind": "switch", "prop": "inset", "labelKey": "components.list_subheader.playground.inset", "defaultValue": false, "labelFallback": "Inset"}, {"kind": "switch", "prop": "sticky", "labelKey": "components.list_subheader.playground.sticky", "defaultValue": false, "labelFallback": "Sticky"}]}, "previewVariants": [{"label": "default", "props": {"title": "Section header"}}, {"label": "inset", "props": {"inset": true, "title": "Inset header"}}, {"label": "sticky", "props": {"title": "Sticky header", "sticky": true}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('65663bae-4cc0-4c41-9cb3-e7757fc5b832', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'component', 'loader', 'Loader', 'Feedback & Status', NULL, 'mdi-loading', 'components.catalog.loader.description', 'Toggle container that swaps between a loading spinner (OrigamProgress circular) and the default slot content. Carries aria-busy and aria-label when loading.', NULL, NULL, 'origam-loader', NULL, 'packages/ds/src/components/Loader/OrigamLoader.vue', 'origam', NULL, NULL, '/stories/?story=components-loader--design', '/docs/components/Loader/OrigamLoader.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.loader.a11y.aria_busy_note", "noteFallback": "While loading, the root carries <code>aria-busy=\"true\"</code> and <code>aria-label=\"Loading\"</code> (or the custom loadingText). Screen readers announce the loading state."}, {"noteKey": "components.loader.a11y.live_region_note", "noteFallback": "For critical async operations that change page content, consider wrapping OrigamLoader in a live region (<code>aria-live=\"polite\"</code>) so the transition from loading to loaded is announced."}], "roles": [], "keyboard": []}, "tokens": {"excerpt": [{"type": "other", "value": "100%", "tokenPath": "--origam-loader---height", "descriptionKey": "components.loader.tokens.height", "descriptionFallback": "Default height of the loader root."}, {"type": "other", "value": "auto", "tokenPath": "--origam-loader__progress---margin", "descriptionKey": "components.loader.tokens.progress_margin", "descriptionFallback": "Margin around the progress element in the loader slot."}, {"type": "other", "value": "fixed", "tokenPath": "--origam-loader__fullscreen---position", "descriptionKey": "components.loader.tokens.fullscreen_position", "descriptionFallback": "Position in fullscreen mode."}, {"type": "other", "value": "100vh", "tokenPath": "--origam-loader__fullscreen---height", "descriptionKey": "components.loader.tokens.fullscreen_height", "descriptionFallback": "Height in fullscreen mode."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"24\" y=\"24\" width=\"300\" height=\"152\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <circle cx=\"174\" cy=\"96\" r=\"28\" fill=\"none\" stroke=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.20))\" stroke-width=\"4\"/>\n  <path d=\"M174 68 A28 28 0 0 1 202 96\" fill=\"none\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n  <text x=\"174\" y=\"148\" font-size=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">loading=true → #loader slot</text>\n  <rect x=\"376\" y=\"24\" width=\"300\" height=\"152\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1.5\"/>\n  <text x=\"526\" y=\"96\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#default slot content</text>\n  <text x=\"526\" y=\"112\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">loading=false</text>\n  <circle cx=\"32\" cy=\"32\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"32\" y=\"36.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"384\" cy=\"32\" r=\"10\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"384\" y=\"36.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"174\" cy=\"96\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"174\" y=\"100\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<component\n  :is=\"tag\"\n  :aria-busy=\"isLoading || undefined\"\n  :aria-label=\"isLoading ? ''Loading'' : undefined\"\n  class=\"origam-loader\"\n>\n  <!-- shown when loading=true -->\n  <template v-if=\"isLoading\">\n    <slot name=\"loader\">\n      <origam-progress\n        :color=\"color\"\n        :size=\"23\"\n        type=\"circular\"\n        :width=\"2\"\n        class=\"origam-loader__progress\"\n        indeterminate\n      />\n    </slot>\n  </template>\n  <!-- shown when loading=false -->\n  <template v-else>\n    <slot name=\"default\" />\n  </template>\n</component>", "legend": [{"cls": ".origam-loader (loading)", "num": 1, "descriptionKey": "components.loader.anatomy.loading_state", "descriptionFallback": "Root element while <code>loading</code> is truthy. Carries <code>aria-busy=\"true\"</code> and <code>aria-label=\"Loading\"</code>. Renders the <code>#loader</code> slot."}, {"cls": ".origam-loader (loaded)", "num": 2, "descriptionKey": "components.loader.anatomy.loaded_state", "descriptionFallback": "Root element while <code>loading</code> is falsy. <code>aria-busy</code> and <code>aria-label</code> are absent. Renders the <code>#default</code> slot."}, {"cls": ".origam-loader__progress", "num": 3, "descriptionKey": "components.loader.anatomy.progress", "descriptionFallback": "OrigamProgress circular spinner injected in the default <code>#loader</code> slot. <code>margin: auto</code> centres it. Can be replaced by a custom slot."}], "classes": [{"cls": "origam-loader", "descriptionKey": "components.loader.anatomy.root", "descriptionFallback": "Root element. height: 100% by default."}, {"cls": "origam-loader--fullscreen", "descriptionKey": "components.loader.anatomy.fullscreen", "descriptionFallback": "Optional consumer-applied modifier. position: fixed; top: 0; left: 0; 100vw × 100vh."}, {"cls": "origam-loader__progress", "descriptionKey": "components.loader.anatomy.progress", "descriptionFallback": "OrigamProgress element rendered in the default loader slot. margin: auto centres it."}], "svgDesc": "Schematic of the Loader component in its two states: loading and loaded.", "svgTitle": "Anatomy of OrigamLoader", "rootClass": "origam-loader", "figcaption": "Anatomy of <code>&lt;origam-loader&gt;</code> — ① loading state (root with aria-busy, spinner rendered via #loader slot), ② loaded state (#default content visible), ③ OrigamProgress spinner (size=23, width=2, type=circular).", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-loader---height", "defaultValue": "100%", "descriptionKey": "components.loader.css_vars.height", "descriptionFallback": "Height of the root element. Defaults to 100% to fill its parent."}, {"name": "--origam-loader__fullscreen---position", "defaultValue": "fixed", "descriptionKey": "components.loader.css_vars.fullscreen_position", "descriptionFallback": "Position value when the fullscreen modifier class is applied."}, {"name": "--origam-loader__fullscreen---height", "defaultValue": "100vh", "descriptionKey": "components.loader.css_vars.fullscreen_height", "descriptionFallback": "Height in fullscreen mode."}, {"name": "--origam-loader__fullscreen---width", "defaultValue": "100vw", "descriptionKey": "components.loader.css_vars.fullscreen_width", "descriptionFallback": "Width in fullscreen mode."}, {"name": "--origam-loader__progress---margin", "defaultValue": "auto", "descriptionKey": "components.loader.css_vars.progress_margin", "descriptionFallback": "Margin around the progress spinner — auto centres it."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.loader.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.loader.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.loader.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.loader.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.loader.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.loader.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "loading", "labelKey": "components.loader.playground.loading", "defaultValue": true, "labelFallback": "Loading"}, {"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}], "labelKey": "components.loader.playground.color", "defaultValue": "primary", "labelFallback": "Spinner color"}, {"kind": "select", "prop": "tag", "options": [{"label": "span", "value": "span"}, {"label": "div", "value": "div"}, {"label": "section", "value": "section"}], "labelKey": "components.loader.playground.tag", "defaultValue": "span", "labelFallback": "Tag"}]}, "previewVariants": [{"label": "loading", "props": {"color": "primary", "loading": true}, "slotContent": "Content hidden while loading"}, {"label": "loaded", "props": {"loading": false}, "slotContent": "Content visible"}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
