INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('75561662-ca17-4039-b2e0-123c46f288da', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'component', 'item-group', 'ItemGroup', 'Layout & Structure', NULL, 'mdi-view-list-outline', 'components.catalog.item_group.description', 'Renderless selection container that tracks which child OrigamItem elements are selected. Single, multiple and mandatory selection modes.', NULL, NULL, 'origam-item-group', NULL, 'packages/ds/src/components/ItemGroup/OrigamItemGroup.vue', 'origam', NULL, NULL, '/stories/?story=components-itemgroup--design', '/docs/components/ItemGroup/OrigamItemGroup.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.item_group.a11y.role_note", "noteFallback": "OrigamItemGroup is renderless and carries no ARIA role itself. Consumers must ensure the rendered children have appropriate roles (button, tab, radio, etc.)."}, {"noteKey": "components.item_group.a11y.selected_class_note", "noteFallback": "The selectedClass is injected as a CSS class — not an ARIA attribute. Consumers are responsible for mapping the selected state to aria-pressed, aria-selected or aria-checked on their child elements."}], "roles": [], "keyboard": [{"key": "Tab", "actionKey": "components.item_group.a11y.key_tab", "actionFallback": "Moves focus through the child items. Keyboard navigation is delegated to the rendered child elements (e.g. origam-btn with role=\"button\")."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"24\" y=\"32\" width=\"652\" height=\"136\" rx=\"4\" fill=\"none\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"6 3\"/>\n  <rect x=\"52\" y=\"64\" width=\"168\" height=\"72\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"266\" y=\"64\" width=\"168\" height=\"72\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"480\" y=\"64\" width=\"168\" height=\"72\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1.5\"/>\n  <text x=\"136\" y=\"104\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-item ①</text>\n  <text x=\"350\" y=\"100\" font-size=\"11\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-item ②</text>\n  <text x=\"350\" y=\"116\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\" font-style=\"italic\">selected</text>\n  <text x=\"564\" y=\"104\" font-size=\"11\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-item ③</text>\n  <circle cx=\"32\" cy=\"40\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"32\" y=\"44.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <line x1=\"42\" y1=\"40\" x2=\"76\" y2=\"40\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"80\" y=\"36\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-item-group</text>\n  <circle cx=\"60\" cy=\"72\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"60\" y=\"76\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"274\" cy=\"72\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"274\" y=\"76\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<!-- renderless root — no visual chrome -->\n<origam-item-group v-model=\"selected\" tag=\"div\">\n  <!-- default slot exposes: { isSelected, select, next, prev, selected } -->\n  <slot :is-selected=\"isSelected\" :select=\"select\" :next=\"next\" :prev=\"prev\" :selected=\"selected\" />\n</origam-item-group>", "legend": [{"cls": ".origam-item-group", "num": 1, "descriptionKey": "components.item_group.anatomy.root", "descriptionFallback": "Root element. Renderless — no visual chrome. Provides group context via <code>ORIGAM_ITEM_GROUP_KEY</code>."}, {"cls": "origam-item (unselected)", "num": 2, "descriptionKey": "components.item_group.anatomy.item_unselected", "descriptionFallback": "Child item not currently selected. Exposes <code>isSelected=false</code> to its default slot."}, {"cls": "origam-item (selected)", "num": 3, "descriptionKey": "components.item_group.anatomy.item_selected", "descriptionFallback": "Child item that is currently selected. Receives <code>selectedClass</code> and exposes <code>isSelected=true</code>."}], "classes": [{"cls": "origam-item-group", "descriptionKey": "components.item_group.anatomy.root", "descriptionFallback": "Root element. Renderless selection container."}], "svgDesc": "Schematic of the ItemGroup renderless container with three child items.", "svgTitle": "Anatomy of OrigamItemGroup", "rootClass": "origam-item-group", "figcaption": "Anatomy of <code>&lt;origam-item-group&gt;</code> — renderless root (①) wrapping child <code>&lt;origam-item&gt;</code> elements (②③). The selected item carries the <code>selectedClass</code>.", "svgViewBox": "0 0 700 200"}, "cssVars": [], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.item_group.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child."}, {"name": "next", "type": "() => void", "descriptionKey": "components.item_group.exposed.next", "descriptionFallback": "Selects the next item in DOM order."}, {"name": "prev", "type": "() => void", "descriptionKey": "components.item_group.exposed.prev", "descriptionFallback": "Selects the previous item in DOM order."}, {"name": "select", "type": "(id: number, value: boolean) => void", "descriptionKey": "components.item_group.exposed.select", "descriptionFallback": "Programmatically toggle the selected state of an item by its internal id."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.item_group.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.item_group.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.item_group.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.item_group.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.item_group.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "multiple", "labelKey": "components.item_group.playground.multiple", "defaultValue": false, "labelFallback": "Multiple selection"}, {"kind": "switch", "prop": "mandatory", "labelKey": "components.item_group.playground.mandatory", "defaultValue": false, "labelFallback": "Mandatory (keep at least one)"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.item_group.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "select", "prop": "tag", "options": [{"label": "div", "value": "div"}, {"label": "ul", "value": "ul"}, {"label": "section", "value": "section"}], "labelKey": "components.item_group.playground.tag", "defaultValue": "div", "labelFallback": "Tag"}], "defaultSlotContent": ""}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('719e1896-cf05-4bc0-859a-dfd643fd8f48', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'component', 'item-group-item', 'ItemGroupItem', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'origam-item-group-item', NULL, 'packages/ds/src/components/ItemGroup/OrigamItemGroupItem.vue', NULL, NULL, NULL, NULL, NULL, 'item-group', '{"playground": {"controls": [{"kind": "switch", "prop": "disabled", "labelKey": "components.item_group_item.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}], "defaultSlotContent": "Content"}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('dba832ba-794f-40ed-8edc-491973799206', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'component', 'kbd', 'Kbd', 'Typography', NULL, 'mdi-keyboard-outline', 'components.catalog.kbd.description', 'Keyboard shortcut renderer using semantic <kbd> elements with filled, outlined and tonal variants.', NULL, NULL, 'origam-kbd', NULL, 'packages/ds/src/components/Kbd/OrigamKbd.vue', 'origam', NULL, NULL, '/stories/?story=components-kbd--design', '/docs/components/Kbd/OrigamKbd.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.kbd.a11y.semantic_note", "noteFallback": "Uses native <kbd> HTML elements — screen readers announce these as keyboard input, requiring no ARIA role override."}, {"noteKey": "components.kbd.a11y.separator_note", "noteFallback": "The separator span in combination mode carries aria-hidden=\"true\" so screen readers skip the \"+\" character and only read the key names."}, {"noteKey": "components.kbd.a11y.contrast_note", "noteFallback": "The v-contrast directive automatically adjusts the text color to ensure WCAG contrast requirements are met against the background."}], "roles": [], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---overlay)", "tokenPath": "--origam-kbd---background-color", "descriptionKey": "components.kbd.tokens.background_color", "descriptionFallback": "Default key background."}, {"type": "dimension", "value": "var(--origam-radius---sm)", "tokenPath": "--origam-kbd---border-radius", "descriptionKey": "components.kbd.tokens.border_radius", "descriptionFallback": "Default key border radius (4px)."}, {"type": "fontFamily", "value": "var(--origam-font__family---mono)", "tokenPath": "--origam-kbd---font-family", "descriptionKey": "components.kbd.tokens.font_family", "descriptionFallback": "Monospace font stack for key labels."}, {"type": "fontWeight", "value": "var(--origam-font__weight---medium)", "tokenPath": "--origam-kbd---font-weight", "descriptionKey": "components.kbd.tokens.font_weight", "descriptionFallback": "Key label font weight."}, {"type": "shadow", "value": "var(--origam-shadow---xs)", "tokenPath": "--origam-kbd---box-shadow", "descriptionKey": "components.kbd.tokens.box_shadow", "descriptionFallback": "Key shadow for the 3D depth effect."}, {"type": "dimension", "value": "var(--origam-space---1)", "tokenPath": "--origam-kbd---gap", "descriptionKey": "components.kbd.tokens.gap", "descriptionFallback": "Gap between keys in combination mode."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <text x=\"350\" y=\"35\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">SINGLE KEY</text>\n  <rect x=\"270\" y=\"45\" width=\"160\" height=\"50\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---subtle, #d4d4d4)\" stroke-width=\"1.5\"/>\n  <text x=\"350\" y=\"76\" font-size=\"14\" fill=\"var(--origam-color__text---primary, #171717)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" font-weight=\"500\">Ctrl</text>\n  <circle cx=\"278\" cy=\"53\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"278\" y=\"57.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <text x=\"350\" y=\"125\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">COMBINATION</text>\n  <rect x=\"170\" y=\"140\" width=\"80\" height=\"40\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---subtle, #d4d4d4)\" stroke-width=\"1.5\"/>\n  <text x=\"210\" y=\"166\" font-size=\"13\" fill=\"var(--origam-color__text---primary, #171717)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" font-weight=\"500\">Ctrl</text>\n  <text x=\"270\" y=\"163\" font-size=\"14\" fill=\"var(--origam-color__text---secondary, rgba(0,0,0,0.55))\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">+</text>\n  <rect x=\"290\" y=\"140\" width=\"50\" height=\"40\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---subtle, #d4d4d4)\" stroke-width=\"1.5\"/>\n  <text x=\"315\" y=\"166\" font-size=\"13\" fill=\"var(--origam-color__text---primary, #171717)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\" font-weight=\"500\">S</text>\n  <circle cx=\"178\" cy=\"148\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"178\" y=\"152.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"270\" cy=\"148\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"270\" y=\"152.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <text x=\"350\" y=\"195\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">Renders native &lt;kbd&gt; HTML elements — always semantic</text>\n", "code": "<!-- Single key -->\n<kbd class=\"origam-kbd origam-kbd--variant-outlined\">Ctrl</kbd>\n\n<!-- Combination -->\n<kbd class=\"origam-kbd origam-kbd--combination origam-kbd--variant-outlined\">\n  <kbd class=\"origam-kbd__key\">Ctrl</kbd>\n  <span class=\"origam-kbd__separator\" aria-hidden=\"true\">+</span>\n  <kbd class=\"origam-kbd__key\">S</kbd>\n</kbd>", "legend": [{"cls": ".origam-kbd", "num": 1, "descriptionKey": "components.kbd.anatomy.root", "descriptionFallback": "Root <code>&lt;kbd&gt;</code> element. In single-key mode, renders the key directly. The <code>v-contrast</code> directive auto-adjusts text color for accessibility."}, {"cls": ".origam-kbd__key", "num": 2, "descriptionKey": "components.kbd.anatomy.key", "descriptionFallback": "Individual key element in combination mode. Each item in the <code>combination</code> array renders as a nested <code>&lt;kbd class=\"origam-kbd__key\"&gt;</code>."}, {"cls": ".origam-kbd__separator", "num": 3, "descriptionKey": "components.kbd.anatomy.separator", "descriptionFallback": "Character rendered between keys in combination mode. <code>aria-hidden=\"true\"</code> so screen readers skip it. Default: \"+\"."}], "classes": [{"cls": "origam-kbd", "descriptionKey": "components.kbd.anatomy.root", "descriptionFallback": "Root <kbd> element. Shared key-surface styles via @mixin key-surface."}, {"cls": "origam-kbd--variant-outlined", "descriptionKey": "components.kbd.anatomy.variant_outlined", "descriptionFallback": "Outlined variant: border + bottom shadow for 3D key effect."}, {"cls": "origam-kbd--variant-filled", "descriptionKey": "components.kbd.anatomy.variant_filled", "descriptionFallback": "Filled variant: surface-overlay background with stronger shadow."}, {"cls": "origam-kbd--variant-tonal", "descriptionKey": "components.kbd.anatomy.variant_tonal", "descriptionFallback": "Tonal variant: tinted background, no border, no shadow."}, {"cls": "origam-kbd--combination", "descriptionKey": "components.kbd.anatomy.combination", "descriptionFallback": "Applied when combination prop is set. Makes the root transparent; each __key inherits key-surface styles."}, {"cls": "origam-kbd__key", "descriptionKey": "components.kbd.anatomy.key", "descriptionFallback": "Individual nested key in combination mode. Inherits key-surface styles."}, {"cls": "origam-kbd__separator", "descriptionKey": "components.kbd.anatomy.separator", "descriptionFallback": "Separator text between keys. aria-hidden=\"true\"."}], "svgDesc": "Schematic of the Kbd component with 3 numbered parts: root key, combination wrapper, and separator.", "svgTitle": "Anatomy of OrigamKbd", "rootClass": "origam-kbd", "figcaption": "Anatomy of <code>&lt;origam-kbd&gt;</code>. Single-key mode ① renders one <code>&lt;kbd&gt;</code>; combination mode ② wraps individual keys in nested <code>&lt;kbd&gt;</code> elements separated by a ③ span.", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-kbd---background-color", "defaultValue": "{color.surface.overlay}", "descriptionKey": "components.kbd.css_vars.background_color", "descriptionFallback": "Key background color. Overridden per variant."}, {"name": "--origam-kbd---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.kbd.css_vars.color", "descriptionFallback": "Key foreground color. Auto-adjusted by v-contrast directive."}, {"name": "--origam-kbd---border-color", "defaultValue": "{color.border.subtle}", "descriptionKey": "components.kbd.css_vars.border_color", "descriptionFallback": "Key border color."}, {"name": "--origam-kbd---border-width", "defaultValue": "1px", "descriptionKey": "components.kbd.css_vars.border_width", "descriptionFallback": "Border width. Set to 0 for tonal variant."}, {"name": "--origam-kbd---border-radius", "defaultValue": "4px", "descriptionKey": "components.kbd.css_vars.border_radius", "descriptionFallback": "Key border radius. Overridden by the rounded prop."}, {"name": "--origam-kbd---font-family", "defaultValue": "{font.family.mono}", "descriptionKey": "components.kbd.css_vars.font_family", "descriptionFallback": "Monospace font family for the key label."}, {"name": "--origam-kbd---font-weight", "defaultValue": "{font.weight.medium}", "descriptionKey": "components.kbd.css_vars.font_weight", "descriptionFallback": "Key label font weight."}, {"name": "--origam-kbd---box-shadow", "defaultValue": "0 1px 0 0 color-mix(…), inset 0 1px 0 0 color-mix(…)", "descriptionKey": "components.kbd.css_vars.box_shadow", "descriptionFallback": "3D key shadow. Composed of a bottom border-like shadow and an inset highlight. Cleared for tonal/combination variants."}, {"name": "--origam-kbd---gap", "defaultValue": "4px", "descriptionKey": "components.kbd.css_vars.gap", "descriptionFallback": "Gap between keys in combination mode."}, {"name": "--origam-kbd__separator---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.kbd.css_vars.separator_color", "descriptionFallback": "Color of the separator character between keys."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.kbd.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.kbd.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed kbdStyles."}, {"name": "id", "type": "string", "descriptionKey": "components.kbd.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.kbd.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.kbd.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.kbd.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "text", "prop": "text", "labelKey": "components.kbd.playground.text", "defaultValue": "⌘", "labelFallback": "Key text"}, {"kind": "select", "prop": "variant", "options": [{"label": "outlined", "value": "outlined"}, {"label": "filled", "value": "filled"}, {"label": "tonal", "value": "tonal"}], "labelKey": "components.kbd.playground.variant", "defaultValue": "outlined", "labelFallback": "Variant"}, {"kind": "select", "prop": "size", "options": [{"label": "x-small", "value": "x-small"}, {"label": "small", "value": "small"}, {"label": "default", "value": "default"}, {"label": "large", "value": "large"}, {"label": "x-large", "value": "x-large"}], "labelKey": "components.kbd.playground.size", "defaultValue": "default", "labelFallback": "Size"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
