", "descriptionFallback": "Default font size."}, {"type": "fontWeight", "value": "var(--origam-font__weight---regular)", "tokenPath": "--origam-label---font-weight", "descriptionKey": "components.label.tokens.font_weight", "descriptionFallback": "Label font weight."}, {"type": "duration", "value": "var(--origam-motion__duration---normal)", "tokenPath": "--origam-label---transition-duration", "descriptionKey": "components.label.tokens.transition_duration", "descriptionFallback": "Duration of float animation transitions."}, {"type": "color", "value": "var(--origam-color__feedback--danger---fgSubtle)", "tokenPath": "--origam-label---required-indicator-color", "descriptionKey": "components.label.tokens.required_indicator_color", "descriptionFallback": "Color of the asterisk required indicator."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"500\" height=\"160\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"40\" width=\"300\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"120\" y=\"76\" font-size=\"13\" fill=\"var(--origam-color__text---primary, #1a1a2e)\" font-family=\"''JetBrains Mono'',monospace\">Label text</text>\n  <text x=\"240\" y=\"70\" font-size=\"10\" fill=\"var(--origam-color__feedback--danger---bg, #ef4444)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">*</text>\n  <circle cx=\"36\" cy=\"48\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"52.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"248\" cy=\"60\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"248\" y=\"64.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary--