INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('e9f71547-ef00-4320-a1ed-8018a150500c', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'component', 'list', 'List', 'Data Display', NULL, 'mdi-format-list-bulleted', 'components.catalog.list.description', 'Accessible list component with support for navigation, selection, groups, subheaders, icons, avatars, single/multi-line items and keyboard traversal.', NULL, NULL, 'origam-list', NULL, 'packages/ds/src/components/List/OrigamList.vue', 'origam', NULL, NULL, '/stories/?story=components-list--design', '/docs/components/List/OrigamList.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.list.a11y.role_note", "noteFallback": "OrigamList renders with <code>role=\"listbox\"</code>. Individual items receive <code>tabindex=\"-2\"</code> (managed tab focus) while the list root itself holds <code>tabindex=\"0\"</code> when not focused internally."}, {"noteKey": "components.list.a11y.nav_note", "noteFallback": "For navigation lists, prefer wrapping OrigamList in a <code>&lt;nav&gt;</code> landmark and setting <code>tag=\"ul\"</code> on OrigamList with <code>tag=\"li\"</code> on each ListItem."}, {"noteKey": "components.list.a11y.disabled_note", "noteFallback": "When disabled=true, pointer-events and user-select are set to none, but the element remains in the DOM. The list is still focusable — add aria-disabled=\"true\" manually if needed."}], "roles": ["listbox"], "keyboard": [{"key": "ArrowDown", "actionKey": "components.list.a11y.key_arrow_down", "actionFallback": "Moves focus to the next list item."}, {"key": "ArrowUp", "actionKey": "components.list.a11y.key_