e."}, {"type": "dimension", "value": "var(--origam-font__size---md)", "tokenPath": "--origam-list__subheader---font-size", "descriptionKey": "components.list.tokens.subheader_font_size", "descriptionFallback": "Subheader font size."}, {"type": "color", "value": "var(--origam-color__text---secondary)", "tokenPath": "--origam-list-subheader---color", "descriptionKey": "components.list.tokens.subheader_color", "descriptionFallback": "Subheader text color."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"280\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"24\" y=\"24\" width=\"652\" height=\"232\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"24\" y=\"24\" width=\"652\" height=\"32\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"none\"/>\n  <text x=\"56\" y=\"44\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" font-family=\"''JetBrains Mono'',monospace\">SECTION HEADER</text>\n  <rect x=\"24\" y=\"56\" width=\"652\" height=\"48\" rx=\"0\" fill=\"none\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\"/>\n  <rect x=\"40\" y=\"68\" width=\"24\" height=\"24\" rx=\"12\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.12))\"/>\n  <text x=\"52\" y=\"84\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\" font-family=\"sans-serif\">i</text>\n  <text x=\"80\" y=\"79\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #1e0036)\" font-family=\"sans-serif\">List item title</text>\n  <text x=\"80\" y=\"94\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" font-family=\"sans-serif\">Subtitle text</text>\n  <rect x=\"24\" y=\"104\" width=\"652\" height=\"48\" rx=\"0\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"none\"/>\n  <text x=\"80\" y=\"125\" font-size=\"11\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-family=\"sans-serif\">Active item</text>\n  <rect x=\"24\" y=\"152\" width=\"652\" height=\"1\" fill=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\"/>\n  <rect x=\"24\" y=\"153\" width=\"652\" height=\"48\" rx=\"0\" fill=\"none\"/>\n  <text x=\"80\" y=\"182\" font-size=\"11\" fill=\"var(--origam-color__text---primary, #1e0036)\" font-family=\"sans-serif\">Group header (collapsed)</text>\n  <text x=\"660\" y=\"182\" font-size=\"11\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"end\" font-family=\"sans-serif\">▶</text>\n  <rect x=\"24\" y=\"201\" width=\"652\" height=\"48\" rx=\"0\" fill=\"none\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.15))\" stroke-width=\"1\"/>\n  <text x=\"104\" y=\"230\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" font-family=\"sans-serif\">Nested child item</text>\n  <circle cx=\"32\" cy=\"32\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"32\" y=\"36.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"32\" cy=\"80\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"32\" y=\"84\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"32\" cy=\"128\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"32\" y=\"132\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"32\" cy=\"177\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"32\" y=\"181\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"32\" cy=\"225\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"32\" y=\"229\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n", "code": "<!-- role=\"listbox\" — keyboard nav handled by OrigamList script -->\n<component :is=\"tag\" role=\"listbox\" class=\"origam-list\">\n  <!-- ListSubheader (optional) -->\n  <div class=\"origam-list-subheader\">SECTION</div>\n\n  <!-- OrigamListItem — grid: prepend | content | append -->\n  <div class=\"origam-list-item origam-list-item--link\">\n    <span class=\"origam-list-item__overlay\" />\n    <span class=\"origam-list-item__underlay\" />\n    <div class=\"origam-list-item__prepend\"><origam-icon /></div>\n    <div class=\"origam-list-item__content\">\n      <div class=\"origam-list-item__title\">Title</div>\n      <div class=\"origam-list-item__subtitle\">Subtitle</div>\n    </div>\n    <div class=\"origam-list-item__append\"><origam-icon /></div>\n  </div>\n</component>", "legend": [{"cls": ".origam-list", "num": 1, "descriptionKey": "components.list.anatomy.root", "descriptionFallback": "Root element. <code>role=\"listbox\"</code>. Manages keyboard navigation (arrow keys, Home, End) and focus tracking."}, {"cls": ".origam-list-item", "num": 2, "descriptionKey": "components.list.anatomy.item", "descriptionFallback": "Individual row. 3-column grid: prepend | content (title + subtitle) | append. Clickable when link or value is set."}, {"cls": ".origam-list-item--active", "num": 3, "descriptionKey": "components.list.anatomy.item_active", "descriptionFallback": "Active state modifier. Applied when the item value matches the list selection or when active=true."}, {"cls": ".origam-list-group", "num": 4, "descriptionKey": "components.list.anatomy.group", "descriptionFallback": "Collapsible group wrapper. The activator header toggles the open state; nested children indent via CSS var."}, {"cls": ".origam-list-item (nested)", "num": 5, "descriptionKey": "components.list.anatomy.nested_item", "descriptionFallback": "Child item inside a ListGroup. Inherits indent via <code>--origam-list---indent-padding</code> CSS variable."}], "classes": [{"cls": "origam-list", "descriptionKey": "components.list.anatomy.root", "descriptionFallback": "Root element. role=\"listbox\". Keyboard navigation container."}, {"cls": "origam-list--disabled", "descriptionKey": "components.list.anatomy.disabled", "descriptionFallback": "Applied when disabled=true. pointer-events: none; user-select: none."}, {"cls": "origam-list--nav", "descriptionKey": "components.list.anatomy.nav", "descriptionFallback": "Navigation mode. Reduces horizontal padding and adjusts subheader font size."}, {"cls": "origam-list--slim", "descriptionKey": "components.list.anatomy.slim", "descriptionFallback": "Slim mode. Reduces prepend area width to 28 px."}, {"cls": "origam-list--one-line", "descriptionKey": "components.list.anatomy.one_line", "descriptionFallback": "Item min-height and subtitle clamp for single-line items."}, {"cls": "origam-list--two-line", "descriptionKey": "components.list.anatomy.two_line", "descriptionFallback": "Item min-height and subtitle clamp for two-line items."}, {"cls": "origam-list--three-line", "descriptionKey": "components.list.anatomy.three_line", "descriptionFallback": "Item min-height and subtitle clamp for three-line items."}, {"cls": "origam-list-item", "descriptionKey": "components.list.anatomy.item", "descriptionFallback": "Individual row — 3-column grid layout."}, {"cls": "origam-list-item__overlay", "descriptionKey": "components.list.anatomy.item_overlay", "descriptionFallback": "Hover/active scrim. opacity animates on hover (0.08) and active (0.12)."}, {"cls": "origam-list-item__underlay", "descriptionKey": "components.list.anatomy.item_underlay", "descriptionFallback": "Absolute underlay reserved for compositing effects."}, {"cls": "origam-list-item__prepend", "descriptionKey": "components.list.anatomy.item_prepend", "descriptionFallback": "Prepend zone (grid-area: prepend). Hosts icon, avatar or custom slot."}, {"cls": "origam-list-item__content", "descriptionKey": "components.list.anatomy.item_content", "descriptionFallback": "Content zone (grid-area: content). Contains title + subtitle + default slot."}, {"cls": "origam-list-item__title", "descriptionKey": "components.list.anatomy.item_title", "descriptionFallback": "Item title. Single-line ellipsis by default."}, {"cls": "origam-list-item__subtitle", "descriptionKey": "components.list.anatomy.item_subtitle", "descriptionFallback": "Item subtitle. Clamped to 1–3 lines depending on lines prop."}, {"cls": "origam-list-item__append", "descriptionKey": "components.list.anatomy.item_append", "descriptionFallback": "Append zone (grid-area: append). Hosts trailing icon, avatar or custom slot."}, {"cls": "origam-list-item--active", "descriptionKey": "components.list.anatomy.item_active", "descriptionFallback": "Active item. The overlay opacity increases to 0.12."}, {"cls": "origam-list-item--disabled", "descriptionKey": "components.list.anatomy.item_disabled", "descriptionFallback": "Disabled item. pointer-events: none; opacity: 0.6."}, {"cls": "origam-list-item--link", "descriptionKey": "components.list.anatomy.item_link", "descriptionFallback": "Clickable item. cursor: pointer; adds ripple and keyboard handler."}, {"cls": "origam-list-subheader", "descriptionKey": "components.list.anatomy.subheader", "descriptionFallback": "Section label. Font size, color and sticky positioning controlled via CSS vars."}], "svgDesc": "Schematic of the List component with subheader, items and group.", "svgTitle": "Anatomy of OrigamList", "rootClass": "origam-list", "figcaption": "Anatomy of <code>&lt;origam-list&gt;</code> — 5 structural zones: root (①), ListItem (②), active item (③), ListGroup activator (④) and nested child item (⑤).", "svgViewBox": "0 0 700 280"}, "cssVars": [{"name": "--origam-list---background", "defaultValue": "{color.surface.default}", "d