ular__underlay---color", "descriptionKey": "components.progress_circular.tokens.underlay_color", "descriptionFallback": "Background ring color — muted track."}, {"type": "number", "value": "var(--origam-opacity---50)", "tokenPath": "--origam-progress-circular__underlay---opacity", "descriptionKey": "components.progress_circular.tokens.underlay_opacity", "descriptionFallback": "Background ring opacity."}, {"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-progress-circular__overlay---color", "descriptionKey": "components.progress_circular.tokens.overlay_color", "descriptionFallback": "Default foreground arc color (overridden by color prop at runtime)."}, {"type": "duration", "value": "var(--origam-motion__duration---medium)", "tokenPath": "--origam-progress-circular---transition-duration", "descriptionKey": "components.progress_circular.tokens.transition_duration", "descriptionFallback": "Arc transition duration in determinate mode."}, {"type": "duration", "value": "1400ms", "tokenPath": "--origam-progress-circular---indeterminate-duration", "descriptionKey": "components.progress_circular.tokens.indeterminate_duration", "descriptionFallback": "Duration of the indeterminate spin/dash SVG animations."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #f8f9fa)\" rx=\"4\"/>\n  <g transform=\"translate(120, 40)\">\n    <circle cx=\"60\" cy=\"60\" r=\"50\" fill=\"none\" stroke=\"var(--origam-color__surface---disabled, #e9d5ff)\" stroke-width=\"8\" opacity=\"0.5\"/>\n    <circle cx=\"60\" cy=\"60\" r=\"50\" fill=\"none\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"8\" stroke-dasharray=\"188 314\" stroke-dashoffset=\"0\" stroke-linecap=\"round\" transform=\"rotate(-90 60 60)\"/>\n    <text x=\"60\" y=\"65\" font-size=\"14\" fill=\"var(--origam-color__text---primary, 