INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('a2f11574-987f-4ab2-ad65-da05717ae443', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'component', 'picker-title', 'PickerTitle', 'Overlay & Surface', NULL, 'mdi-text-box-outline', 'components.catalog.picker_title.description', 'Title strip rendered at the top of a Picker panel. Displays uppercase text with configurable color and background color theming.', NULL, NULL, 'origam-picker-title', NULL, 'packages/ds/src/components/Picker/OrigamPickerTitle.vue', 'origam', NULL, NULL, '/stories/?story=components-datepicker--design', '/docs/components/Picker/OrigamPicker.html', 'picker', '{"a11y": {"notes": [{"noteKey": "components.picker_title.a11y.semantic", "noteFallback": "PickerTitle renders as a generic div by default. For improved semantics, pass tag=\"h2\" (or the appropriate heading level) so screen readers announce it as a section heading inside the picker dialog."}, {"noteKey": "components.picker_title.a11y.no_interactive", "noteFallback": "This component is purely presentational — it has no interactive elements and no ARIA role by default."}], "roles": [], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"500\" height=\"140\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"30\" y=\"40\" width=\"440\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"30\" y=\"40\" width=\"440\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" st