ons": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}], "labelKey": "components.select.playground.color", "defaultValue": "primary", "labelFallback": "Color"}, {"kind": "select", "prop": "density", "options": [{"label": "compact", "value": "compact"}, {"label": "default", "value": "default"}, {"label": "comfortable", "value": "comfortable"}], "labelKey": "components.select.playground.density", "defaultValue": "default", "labelFallback": "Density"}, {"kind": "switch", "prop": "clearable", "labelKey": "components.select.playground.clearable", "defaultValue": false, "labelFallback": "Clearable"}, {"kind": "switch", "prop": "multiple", "labelKey": "components.select.playground.multiple", "defaultValue": false, "labelFallback": "Multiple"}, {"kind": "switch", "prop": "chips", "labelKey": "components.select.playground.chips", "defaultValue": false, "labelFallback": "Chips"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.select.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}]}, "previewVariants": [{"label": "single", "props": {"items": ["Vue", "React", "Svelte"], "label": "Framework"}}, {"label": "with value", "props": {"items": ["Vue", "React", "Svelte"], "label": "Framework", "modelValue": "Vue"}}, {"label": "outlined", "props": {"items": ["primary", "secondary", "success"], "label": "Color", "variant": "outlined"}}, {"label": "disabled", "props": {"items": ["Vue", "React"], "label": "Disabled", "disabled": true, "modelValue": "Vue"}, "ariaLabel": "Disabled select"}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('93a087f4-7914-45a8-9b4d-13c0a9d6b79c', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'component', 'selection-control', 'SelectionControl', 'Form & Input', NULL, 'mdi-checkbox-marked-circle-outline', 'components.catalog.selection_control.description', 'Base selection-control primitive used by Checkbox, Radio, Switch and similar inputs. Renders a ripple zone, a native input and a label with full ARIA support.', NULL, NULL, 'origam-selection-control', NULL, 'packages/ds/src/components/SelectionControl/OrigamSelectionControl.vue', 'origam', NULL, NULL, '/stories/?story=components-selection-control--design', '/docs/components/SelectionControl/OrigamSelectionControl.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.selection_control.a11y.native_note", "noteFallback": "A native <input type=\"checkbox|radio\"> is always rendered (even when the input slot is customised). This ensures browser-native focus, keyboard handling and form participation."}, {"noteKey": "components.selection_control.a11y.aria_checked_note", "noteFallback": "aria-checked is set automatically by the native input. For type=\"checkbox\", aria-checked is forwarded explicitly via the :aria-checked binding."}, {"noteKey": "components.selection_control.a11y.label_note", "noteFallback": "The label is wired to the input via for/id. Clicking the label toggles the control and fires click:label."}, {"noteKey": "components.selection_control.a11y.error_note", "noteFallback": "When error=true, the label and icon adopt --origam-selection-control---color-error for visual feedback. No aria-invalid is set at this layer — use OrigamInput / form-level components for validation semantics."}], "roles": ["checkbox", "radio"], "keyboard": [{"key": "Space", "actionKey": "components.selection_control.a11y.key_space", "actionFallback": "Toggles the checkbox or selects the radio option."}, {"key": "Tab", "actionKey": "components.selection_control.a11y.key_tab", "actionFallback": "Moves focus to the next interactive element."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__text---primary)", "tokenPath": "--origam-selection-control---color", "descriptionKey": "components.selection_control.tokens.color", "descriptionFallback": "Default control color."}, {"type": "color", "value": "var(--origam-color__text---disabled)", "tokenPath": "--origam-selection-control---color-disabled", "descriptionKey": "components.selection_control.tokens.color_disabled", "descriptionFallback": "Color when disabled."}, {"type": "number", "value": "var(--origam-opacity---50)", "tokenPath": "--origam-selection-control---opacity-disabled", "descriptionKey": "components.selection_control.tokens.opacity_disabled", "descriptionFallback": "Opacity when disabled."}, {"type": "dimension", "value": "40px", "tokenPath": "--origam-selection-control__wrapper---width", "descriptionKey": "components.selection_control.tokens.wrapper_width", "descriptionFallback": "Base width of the ripple wrapper (before density offset)."}, {"type": "dimension", "value": "40px", "tokenPath": "--origam-selection-control__wrapper---height", "descriptionKey": "components.selection_control.tokens.wrapper_height", "descriptionFallback": "Base height of the ripple wrapper."}, {"type": "duration", "value": "var(--origam-motion__duration---medium)", "tokenPath": "--origam-selection-control---transition-duration", "descriptionKey": "components.selection_control.tokens.transition_duration", "descriptionFallback": "Transition duration for icon/color animations."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"520\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"480\" height=\"140\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\" stroke-dasharray=\"6 3\"/>\n  <rect x=\"40\" y=\"50\" width=\"60\" height=\"60\" rx=\"30\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1.5\"/>\n  <text x=\"70\" y=\"85\" font-size=\"18\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">✓</text>\n  <rect x=\"115\" y=\"68\" width=\"220\" height=\"24\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\"/>\n  <text x=\"225\" y=\"85\" font-size=\"12\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">Label text</text>\n  <circle cx=\"28\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"50\" cy=\"60\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"50\" y=\"64\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"70\" cy=\"54\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"70\" y=\"58\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"70\" cy=\"82\" r=\"8\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"70\" y=\"86\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"130\" cy=\"60\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"130\" y=\"64\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n", "code": "<div class=\"origam-selection-control origam-selection-control--dirty\">\n  <!-- wrapper: ripple target + background color -->\n  <div class=\"origam-selection-control__wrapper\">\n    <!-- input zone with v-ripple -->\n    <div class=\"origam-selection-control__input\">\n      <!-- icon (true/false icon) -->\n      <origam-icon :icon=\"icon\" :color=\"bgColor\" />\n      <!-- visually hidden native input -->\n      <input type=\"checkbox\" :id :name :value :checked :disabled />\n    </div>\n  </div>\n\n  <!-- label -->\n  <div class=\"origam-selection-control__label\">\n    <origam-label :for=\"id\" :text=\"label\" :color=\"color\" />\n  </div>\n</div>", "legend": [{"cls": ".origam-selection-control", "num": 1, "descriptionKey": "components.selection_control.anatomy.root", "descriptionFallback": "Root element. Flex-row, aligns wrapper and label. Carries state modifiers (dirty, disabled, error, focused, inline)."}, {"cls": ".origam-selection-control__wrapper", "num": 2, "descriptionKey": "components.selection_control.anatomy.wrapper", "descriptionFallback": "Square wrapper (40px + density). Hosts the ripple zone and the background color layer."}, {"cls": ".origam-selection-control__input", "num": 3, "descriptionKey": "components.selection_control.anatomy.input", "descriptionFallback": "Circular ripple zone (v-ripple). Contains the OrigamIcon (true/falseIcon) and the native input."}, {"cls": "input[type=\"checkbox|radio\"] (native)", "num": 4, "descriptionKey": "components.selection_control.anatomy.native_input", "descriptionFallback": "Visually hidden native input. Manages browser check state, form submission, and screen-reader focus."}, {"cls": ".origam-selection-control__label", "num": 5, "descriptionKey": "components.selection_control.anatomy.label", "descriptionFallback": "Label container. Renders OrigamLabel with for/id wiring."}], "classes": [{"cls": "origam-selection-control", "descriptionKey": "components.selection_control.anatomy.root", "descriptionFallback": "Root block."}, {"cls": "origam-selection-control--dirty", "descriptionKey": "components.selection_control.anatomy.modifier_dirty", "descriptionFallback": "Applied when modelValue is truthy (checked state)."}, {"cls": "origam-selection-control--disabled", "descriptionKey": "components.selection_control.anatomy.modifier_disabled", "descriptionFallback": "Applied when disabled=true."}, {"cls": "origam-selection-control--error", "descriptionKey": "components.selection_control.anatomy.modifier_error", "descriptionFallback": "Applied when error=true. Changes icon and label color."}, {"cls": "origam-selection-control--focused", "descriptionKey": "components.selection_control.anatomy.modifier_focused", "descriptionFallback": "Applied when the native input is focused."}, {"cls": "origam-selection-control--focus-visible", "descriptionKey": "components.selection_control.anatomy.modifier_focus_visible", "descriptionFallback": "Applied on keyboard focus for the visible outline."}, {"cls": "origam-selection-control--inline", "descriptionKey": "components.selection_control.anatomy.modifier_inline", "descriptionFallback": "Applied when inline=true."}, {"cls": "origam-selection-control__wrapper", "descriptionKey": "components.selection_control.anatomy.wrapper", "descriptionFallback": "Inner wrapper hosting ripple and background."}, {"cls": "origam-selection-control__input", "descriptionKey": "components.selection_control.anatomy.input", "descriptionFallback": "Ripple zone with icon and native input."}, {"cls": "origam-selection-control__label", "descriptionKey": "components.selection_control.anatomy.label", "descriptionFallback": "Label container."}], "svgDesc": "Schematic of the SelectionControl component with 5 numbered parts.", "svgTitle": "Anatomy of OrigamSelectionControl", "rootClass": "origam-selection-control", "figcaption": "Anatomy of <code>&lt;origam-selection-control&gt;</code> — 5 parts: root ①, wrapper ②, input zone ③ (with ripple), icon/native input ④, and label ⑤.", "svgViewBox": "0 0 520 180"}, "cssVars": [{"name": "--origam-selection-control---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.selection_control.css_vars.color", "descriptionFallback": "Default text/icon color."}, {"name": "--origam-selection-control---color-disabled", "defaultValue": "{color.text.disabled}", "descriptionKey": "components.selection_control.css_vars.color_disabled", "descriptionFallback": "Color when the control is disabled."}, {"name": "--origam-selection-control---color-error", "defaultValue": "{color.feedback.danger.bg}", "descriptionKey": "components.selection_control.css_vars.color_error", "descriptionFallback": "Color when the control is in error state."}, {"name": "--origam-selection-control---opacity-disabled", "defaultValue": "{opacity.50}", "descriptionKey": "components.selection_control.css_vars.opacity_disabled", "descriptionFallback": "Opacity of the entire control when disabled."}, {"name": "--origam-selection-control---density", "defaultValue": "0px", "descriptionKey": "components.selection_control.css_vars.density", "descriptionFallback": "Density modifier. compact → -8px, comfortable → +8px."}, {"name": "--origam-selection-control---transition-duration", "defaultValue": "{motion.duration.medium}", "descriptionKey": "components.selection_control.css_vars.transition_duration", "descriptionFallback": "Transition duration for icon and color animations."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.selection_control.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to sub-components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.selection_control.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.selection_control.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.selection_control.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.selection_control.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.selection_control.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "type", "options": [{"label": "checkbox", "value": "checkbox"}, {"label": "radio", "value": "radio"}], "labelKey": "components.selection_control.playground.type", "defaultValue": "checkbox", "labelFallback": "Type"}, {"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}], "labelKey": "components.selection_control.playground.color", "defaultValue": "primary", "labelFallback": "Color"}, {"kind": "text", "prop": "label", "labelKey": "components.selection_control.playground.label", "defaultValue": "Option label", "labelFallback": "Label"}, {"kind": "select", "prop": "density", "options": [{"label": "compact", "value": "compact"}, {"label": "default", "value": "default"}, {"label": "comfortable", "value": "comfortable"}], "labelKey": "components.selection_control.playground.density", "defaultValue": "default", "labelFallback": "Density"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.selection_control.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "error", "labelKey": "components.selection_control.playground.error", "defaultValue": false, "labelFallback": "Error"}, {"kind": "switch", "prop": "inline", "labelKey": "components.selection_control.playground.inline", "defaultValue": false, "labelFallback": "Inline"}]}, "previewVariants": [{"label": "unchecked", "props": {"type": "checkbox", "color": "primary", "label": "Unchecked", "trueIcon": "mdi-checkbox-marked", "falseIcon": "mdi-checkbox-blank-outline"}}, {"label": "checked", "props": {"type": "checkbox", "color": "primary", "label": "Checked", "trueIcon": "mdi-checkbox-marked", "falseIcon": "mdi-checkbox-blank-outline", "trueValue": true, "modelValue": true}}, {"label": "radio", "props": {"type": "radio", "color": "secondary", "label": "Radio", "trueIcon": "mdi-radiobox-marked", "falseIcon": "mdi-radiobox-blank"}}, {"label": "error", "props": {"type": "checkbox", "color": "danger", "error": true, "label": "Error", "trueIcon": "mdi-checkbox-marked", "falseIcon": "mdi-checkbox-blank-outline"}}, {"label": "disabled", "props": {"type": "checkbox", "label": "Disabled", "disabled": true, "trueIcon": "mdi-checkbox-marked", "falseIcon": "mdi-checkbox-blank-outline"}, "ariaLabel": "Disabled selection control"}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
