INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('beb6c863-d9f1-4973-8738-984b8c17da66', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'component', 'tab-panel', 'TabPanel', 'Navigation', NULL, 'mdi-tab', 'components.catalog.tab_panel.description', 'A single tab content panel — lazy-mounted by default until first activated, then kept alive via v-show.', NULL, NULL, 'origam-tab-panel', NULL, 'packages/ds/src/components/Tabs/OrigamTabPanel.vue', 'origam', NULL, NULL, '/stories/?story=components-tabs--design', '/docs/components/Tabs/OrigamTabs.html', 'tabs', '{"a11y": {"notes": [{"noteKey": "components.tab_panel.a11y.aria_note", "noteFallback": "OrigamTabPanel sets role=\"tabpanel\" and aria-labelledby pointing to the sibling tab DOM id automatically. No manual ARIA needed."}, {"noteKey": "components.tab_panel.a11y.lazy_note", "noteFallback": "Content is not in the DOM until the panel is first activated (unless eager=true). Screen readers only perceive the content after it is mounted."}, {"noteKey": "components.tab_panel.a11y.vshow_note", "noteFallback": "Inactive panels use v-show (not v-if) after first mount, so content remains in the DOM. Assistive technologies may still reach it via search — the v-show=\"false\" (display: none) does hide it from AT per ARIA spec."}], "roles": ["tabpanel"], "keyboard": [{"key": "Tab", "actionKey": "components.tab_panel.a11y.key_tab", "actionFallback": "Moves focus into the panel content from the tablist."}, {"key": "Shift + Tab", "actionKey": "components.tab_panel.a11y.key_shift_tab", "actionFallback": "Returns focus to the active tab in the tablist."}]}, "tokens": {"excerpt": [{"type": "duration", "value": "var(--origam-motion__duration---fast)", "tokenPath": "--origam-tabs__panel---transition-duration", "descriptionKey": "components.tab_panel.tokens.transition_duration", "descriptionFallback": "Duration of the fade transition when switching panels."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"560\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"40\" y=\"40\" width=\"480\" height=\"100\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"60\" y=\"60\" width=\"440\" height=\"60\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.30))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"280\" y=\"94\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">#default slot content</text>\n  <circle cx=\"52\" cy=\"48\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"52\" y=\"52.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"72\" cy=\"68\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"72\" y=\"72\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <line x1=\"52\" y1=\"36\" x2=\"80\" y2=\"18\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"84\" y=\"16\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-tab-panel</text>\n  <text x=\"280\" y=\"160\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">① = role=\"tabpanel\" · tabindex=0 · aria-labelledby; ② = lazy #default slot</text>\n", "code": "<!-- root: role=\"tabpanel\", tabindex=0, aria-labelledby -->\n<Transition name=\"fade\" mode=\"out-in\">\n  <div\n    v-show=\"isShown\"\n    class=\"origam-tab-panel\"\n    role=\"tabpanel\"\n    tabindex=\"0\"\n    :aria-labelledby=\"tabLabelledBy\"\n  >\n    <!-- lazy slot: only renders after first activation -->\n    <slot v-if=\"hasContent\" name=\"default\" />\n  </div>\n</Transition>", "legend": [{"cls": ".origam-tab-panel", "num": 1, "descriptionKey": "components.tab_panel.anatomy.root", "descriptionFallback": "Root element. Carries <code>role=\"tabpanel\"</code>, <code>tabindex=\"0\"</code> and <code>aria-labelledby</code> pointing to the matching tab id. Hidden via <code>v-show</code> when inactive."}, {"cls": "#default slot", "num": 2, "descriptionKey": "components.tab_panel.anatomy.slot", "descriptionFallback": "Slot content area. Lazy-mounted on first activation via <code>useLazy</code> — renders only after the panel becomes selected for the first time."}], "classes": [{"cls": "origam-tab-panel", "descriptionKey": "components.tab_panel.anatomy.root", "descriptionFallback": "Root element. role=\"tabpanel\", tabindex=0, aria-labelledby, hidden via v-show when inactive."}, {"cls": "origam-tab-panel--active", "descriptionKey": "components.tab_panel.anatomy.active", "descriptionFallback": "Applied when this panel is the selected item in the panels group."}], "svgDesc": "Schematic of the TabPanel component with 2 numbered internal parts.", "svgTitle": "Anatomy of OrigamTabPanel", "rootClass": "origam-tab-panel", "figcaption": "Anatomy of <code>&lt;origam-tab-panel&gt;</code> — 2 parts. The root carries <code>role=\"tabpanel\"</code> and <code>aria-labelledby</code> pointing to the sibling tab; the slot content is lazy-mounted on first activation.", "svgViewBox": "0 0 560 180"}, "cssVars": [{"name": "--origam-tab-panels__panel---padding-block", "defaultValue": "16px", "descriptionKey": "components.tab_panel.css_vars.padding_block", "descriptionFallback": "Vertical padding applied to each tab panel via the parent OrigamTabPanels."}, {"name": "--origam-tab-panels__panel---padding-inline", "defaultValue": "0", "descriptionKey": "components.tab_panel.css_vars.padding_inline", "descriptionFallback": "Horizontal padding applied to each tab panel via the parent OrigamTabPanels."}, {"name": "--origam-tab-panels__panel---transition-duration", "defaultValue": "0.18s", "descriptionKey": "components.tab_panel.css_vars.transition_duration", "descriptionFallback": "Duration of the fade transition when switching panels."}, {"name": "--origam-tab-panels__panel--focus---outline-color", "defaultValue": "currentColor", "descriptionKey": "components.tab_panel.css_vars.focus_outline_color", "descriptionFallback": "Outline color shown on focus-visible for the panel container."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.tab_panel.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.tab_panel.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed panel styles."}, {"name": "id", "type": "string", "descriptionKey": "components.tab_panel.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.tab_panel.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.tab_panel.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.tab_panel.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "eager", "labelKey": "components.tab_panel.playground.eager", "defaultValue": false, "labelFallback": "Eager mount"}], "defaultSlotContent": ""}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('3f0a1bbc-4ee2-4dd2-8c92-795e9ba4a3ea', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'component', 'tab-panels', 'TabPanels', 'Navigation', NULL, 'mdi-tab', 'components.catalog.tab_panels.description', 'Content container that mirrors the tablist selection — orchestrates OrigamTabPanel children with optional fade transition and swipe support.', NULL, NULL, 'origam-tab-panels', NULL, 'packages/ds/src/components/Tabs/OrigamTabPanels.vue', 'origam', NULL, NULL, '/stories/?story=components-tabs--design', '/docs/components/Tabs/OrigamTabs.html', 'tabs', '{"a11y": {"notes": [{"noteKey": "components.tab_panels.a11y.sync_note", "noteFallback": "OrigamTabPanels has no ARIA role of its own — it is a layout orchestrator. ARIA semantics live on each child OrigamTabPanel (role=\"tabpanel\")."}, {"noteKey": "components.tab_panels.a11y.sync_model_note", "noteFallback": "Keep the v-model in sync with the sibling OrigamTabs v-model. Desynchronised models break the aria-controls / aria-labelledby wiring between tabs and panels."}], "roles": [], "keyboard": [{"key": "Swipe left / right", "actionKey": "components.tab_panels.a11y.swipe", "actionFallback": "When swipeable=true, horizontal swipe navigates to the next/previous panel."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-tab-panels__panel---padding-block", "descriptionKey": "components.tab_panels.tokens.padding_block", "descriptionFallback": "Default vertical padding for panel content."}, {"type": "dimension", "value": "var(--origam-space---0)", "tokenPath": "--