INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('149842fd-6589-478a-8694-4c9dec6f3ce4', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'composable', 'use-chart-gauge', 'useChartGauge', NULL, 'Chart', 'mdi-gauge', '', 'Solid-gauge geometry engine for <OrigamChartGauge>. Given a value clamped between min and max, computes the SVG arc paths for the track (full arc background) and the indicator (partial arc proportional to the value), plus centre coordinates and radius values for the value label. Designed to mirror a speedometer-style gauge with a configurable sweep angle and thickness.', NULL, 'function useChartGauge(options: IUseChartGaugeOptions): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('406dd271-05c3-4b7e-b89a-e62fd188e697', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'composable', 'use-chart-header-typography', 'useChartHeaderTypography', 'Chart', 'Chart', NULL, NULL, NULL, NULL, 'function useChartHeaderTypography(props: ITypographyProps): { headerTypographyStyles: ComputedRef<StyleValue>; }', NULL, NULL, 'packages/ds/src/composables/Chart/chart-header-typography.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('c79b0f1b-f15a-460c-820d-f70f42ddbd01', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'composable', 'use-chart-zoom', 'useChartZoom', NULL, 'Chart', 'mdi-magnify-plus-outline', '', 'Manages interactive zoom and pan state for OrigamChartCartesian. The zoom window is expressed as a closed [zoomStart, zoomEnd] range of category indices. Provides scroll-wheel zoom, drag-to-select zoom, and programmatic pan, all with clamping invariants.', NULL, 'function useChartZoom(options: { dataLength: () => number }): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('e9246f59-506a-408a-9b17-8a68c499e4b9', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'composable', 'use-clipboard', 'useClipboard', NULL, 'Clipboard', 'mdi-clipboard-outline', '', 'Headless clipboard composable. Wraps the modern navigator.clipboard.writeText API with a legacy execCommand fallback. Exposes a self-resetting copied flag so consumers do not need to wire the reset timeout themselves. Never throws — callers branch on the returned boolean.', NULL, 'function useClipboard(options?: IUseClipboardOptions): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('95b58a83-2d26-432a-aa4c-d5d6f05c1bff', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'composable', 'use-code', 'useCode', NULL, 'Code', 'mdi-code-tags', '', 'Singleton shiki-powered syntax highlighter. Lazily loads shiki on the first highlight() call to keep the initial bundle small. Bundles only the curated origam language subset and dual light/dark themes so token colours switch via CSS variables without re-tokenising. Caches results in a tiny LRU keyed by (code, lang).', NULL, 'function useCode(): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('b8ca0418-fc6a-45d4-953b-716faf05803e', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'composable', 'use-color', 'useColor', NULL, 'Commons', 'mdi-palette', '', 'Resolve background and text colors from intent tokens or raw CSS values. Part of the classes-first strategy: tokenised intents emit utility classes, custom hex/rgb values emit inline styles.', NULL, 'function useColor(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('a285d3db-522a-4d21-a94f-372386130bd3', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'composable', 'use-color-effect', 'useColorEffect', NULL, 'Commons', 'mdi-palette-swatch', '', 'State-aware (hover / active / disabled) color resolution for components that paint a surface. Resolves bg and fg independently per state axis. Auto-contrasts foreground when only `bgColor` is set. Used by Btn, Card, Chip and ~49 other components.', NULL, 'function useColorEffect(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('21766a49-91bf-4574-bc7e-36e77c9473d5', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'composable', 'use-command', 'useCommand', NULL, 'CommandPalette', 'mdi-console-line', '', 'Process-wide command palette registry. Uses module-scope state (not provide/inject) so commands can be registered from anywhere — feature code, plugins, background services — without coupling to a Vue tree. Two callers on the same module instance see the exact same reactive list.', NULL, 'function useCommand(): {
