INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('48e00e87-6ef2-4c1a-91f9-01fe7e1fc290', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'composable', 'use-padding', 'usePadding', NULL, 'Commons', 'mdi-arrow-collapse-all', '', 'Resolves the `padding` shorthand prop into utility classes for spacing-scale steps (0–12) or inline padding declarations for custom values. Mirror of useMargin for the padding axis.', NULL, 'function usePadding(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('941ade03-7960-459c-aa38-3f1e1ba76a9c', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'composable', 'use-paginated-items', 'usePaginatedItems', 'DataTable', 'DataTable', NULL, NULL, NULL, NULL, 'function usePaginatedItems(options: { items: Ref<readonly (T | IDataTableGroup<T>)[]> startIndex: Ref<number> stopIndex: Ref<number> itemsPerPage: Ref<number> }): { paginatedItems: ComputedRef<readonly (T | IDataTableGroup<T>)[]>; }', NULL, NULL, 'packages/ds/src/composables/DataTable/paginatedItems.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('d36c46c4-c606-433f-bbd4-f94e5341c703', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'composable', 'use-pagination', 'usePagination', NULL, 'DataTable', 'mdi-book-open-page-variant-outline', '', 'Suite of three pagination helpers for OrigamDataTable: createPagination initialises page and itemsPerPage refs from props; providePagination computes derived state (startIndex, stopIndex, pageCount) and provides it to children; usePagination injects the provided pagination context. A fourth helper usePaginatedItems slices the items array for the current page.', NULL, '// Initialise pagination refs from props
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('fbbe6bc6-6be6-499a-b468-e65b7d1b080d', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'composable', 'use-parallax', 'useParallaxRuntime', NULL, 'Parallax', 'mdi-layers-triple-outline', '', 'Headless parallax engine used by OrigamParallax. Maintains a registry of layers, tracks scroll progress via IntersectionObserver, and drives per-frame transforms via requestAnimationFrame. Branches automatically to a CSS scroll-driven animation path (Chrome 115+) when the easing is linear and the browser supports animation-timeline: scroll(). Respects prefers-reduced-motion at OS level.', NULL, 'function useParallaxRuntime(options: IUseParallaxRuntimeOptions): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('ce320f1b-130f-4623-b4d1-dde69e2b568e', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'composable', 'use-parallax-transform', 'useParallaxTransform', NULL, 'Parallax', 'mdi-layers-triple-outline', '', 'Computes CSS transform strings for parallax layer elements based on normalised mouse-position coordinates. Supports five transform types: translate, rotate, depth (3-D tilt), depth-inv (inverted tilt), scale, scale-x, and scale-y. Consumed by OrigamParallax to animate child layers.', NULL, 'function useParallaxTransform(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('bec3c5db-0b4a-40f7-865e-4e534d423023', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'composable', 'use-passed-props', 'usePassedProps', 'Commons', 'Commons', NULL, NULL, NULL, NULL, 'function usePassedProps(_props: T, instanceLabel?: string = ''usePassedProps''): (key: Extract<keyof T, string> | string) => boolean', NULL, NULL, 'packages/ds/src/composables/Commons/passedProps.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('d376ffc7-4e60-43b1-8c8a-aa93e5845e51', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'composable', 'use-password-strength', 'computeStrength', NULL, 'PasswordField', 'mdi-shield-lock-outline', '', 'Pure function (no Vue reactivity needed) that scores a password string on a 0-4 scale based on length, digit presence, case diversity, and special characters. Returns a numeric score and a semantic level (weak / fair / good / strong). Used internally by OrigamPasswordField to drive the strength bar colour and label. No third-party dependencies.', NULL, 'function computeStrength(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('9c2b3bfa-1003-49b2-978c-ad511b101c8c', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'composable', 'use-position', 'usePosition', NULL, 'Commons', 'mdi-map-marker-outline', '', 'Derives CSS positioning classes and inline style declarations from IPositionProps. Emits a BEM modifier class for the position variant (absolute, fixed, sticky, relative, static) and inline top/bottom/left/right properties for any offset props that are set.', NULL, 'function usePosition(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('60a69b61-d456-444b-a623-717a107656d2', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'composable', 'use-progress', 'useProgress', NULL, 'Progress', 'mdi-progress-clock', '', 'Computes all state needed to render a progress bar or circular progress indicator: a normalised 0-100 value from modelValue and max, thickness as a number, a visibility flag tied to IntersectionObserver, and BEM class/style arrays that handle indeterminate, striped, active, and absolute modes. Used by OrigamProgressLinear and OrigamProgressCircular.', NULL, 'function useProgress(props: IProgressTypeProps): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('555f7074-2dea-428e-8a5e-3a5e1aa9f0ed', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'composable', 'use-props', 'useProps', NULL, 'Commons', 'mdi-tune-variant', '', 'Returns a filterProps utility that picks only the keys declared on a component interface from an arbitrary props object, stripping undefined values so that Vue 3 boolean-prop coercion does not silently override withDefaults in child components. Used by composite components (DataTable, List, Select…) to forward a safe subset of their own props to child Origam components.', NULL, 'function useProps<T extends Record<string, any>>(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('4f0b628e-b31e-42c0-bd54-bf9d6fa04d74', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'composable', 'use-qr-code', 'useQrCode', NULL, 'QrCode', 'mdi-qrcode', '', 'Headless QR-code composable. Encodes a string payload using qrcode-generator (Reed-Solomon + matrix masking) and returns a reactive SVG string, the raw module matrix, and the matrix size. The encoder is LRU-cached at module level to avoid rebuilding identical matrices on re-renders. Fully SSR-safe — no DOM API is touched.', NULL, 'function useQrCode(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('a0f12996-0746-4139-84d0-14b8038dd58d', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'const', 'chart-gauge-default-end-angle', 'CHART_GAUGE_DEFAULT_END_ANGLE', 'Chart', NULL, NULL, NULL, NULL, 'export const CHART_GAUGE_DEFAULT_END_ANGLE = Math.PI * 3 / 4', NULL, NULL, 'Math.PI * 3 / 4', 'packages/ds/src/consts/Chart/chart-gauge.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('35fff3a7-17b8-4fc1-8d4a-ffa158560bf1', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'composable', 'use-refs', 'useRefs', NULL, 'Commons', 'mdi-link-variant', '', 'Manages a dynamic array of template refs that is reset before each update cycle. Provides an updateRef(el, i) callback designed for use with :ref in v-for loops, where Vue replaces individual refs by index. The refs array is always fresh (cleared in onBeforeUpdate) so stale elements from a previous render do not leak.', NULL, 'function useRefs<T extends object>(): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('dce3b74c-3c79-4bcd-907e-184bcc37f224', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'composable', 'use-resize-observer', 'useResizeObserver', NULL, 'Commons', 'mdi-resize', '', 'Wraps the native ResizeObserver API with a reactive template ref. Returns a resizeRef to attach to any element and a readonly contentRect that updates on every resize. Automatically disconnects the observer on component unmount. Supports both content-box (default) and border-box measurement.', NULL, 'function useResizeObserver(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('61738ff8-e0e2-46d5-b99a-f8ed19f6acaa', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'composable', 'use-rounded', 'useRounded', NULL, 'Commons', 'mdi-rounded-corner', '', 'Resolves the `rounded` prop to border-radius classes and inline styles. Supports the modern utility taxonomy (xs/sm/md/lg/xl/none/full), the legacy named variants (x-small/small/default/medium/large/x-large/shaped), numbers and free-form CSS values.', NULL, 'function useRounded(
