INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('1540fd31-5aeb-48e0-b0be-87bd8677310e', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'interface', 'i-media-controller-emits', 'IMediaControllerEmits', 'Events & Emits', NULL, NULL, 'interfaces.catalog.i_media_controller_emits.description', 'Emits surfaced by <OrigamMediaController>. The shell calls methods.* directly for the basic ops (toggle play, seek, set volume, set rate, toggle mute, request cast) — those do not bubble. These emits are the ones the parent must handle because the Controller does not own enough context.', 'export interface IMediaControllerEmits {
    (e: ''quality-change'', quality: string): void
    (e: ''download''): void
    (e: ''previous''): void
    (e: ''next''): void
    (e: ''update:loopMode'', mode: TAudioLoopMode): void
    (e: ''update:shuffle'', shuffle: boolean): void
