INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d4627c26-d91b-41c5-afa5-14ef3e53bc8e', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'caf75d99-73d0-423c-8afc-40265211d451', 'appendIcon', 'Ref | ComputedRef', false, NULL, '', 'Optional reactive icon override for the append slot. Same semantics as prependIcon but for the trailing position.', 2, false, NULL, NULL);
