INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d257030a-b3be-4fdb-a4dc-59c442f1da87', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'fae00ec8-bba3-48d5-a3b5-c2548bf4918b', 'props', 'IUseAudioProps', true, NULL, '', 'Props object with audio (URL of the audio source) and playAudio (boolean flag). When playAudio changes to true the composable calls onPlay(); when it changes to false it calls onStop(). When audio changes, wasPlayed and isPlaying are reset.', 0, false, NULL, NULL);
