INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6ed393c1-9f43-4cbf-9381-36ffdbf4526b', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'fa49ef84-73b8-4641-9d1f-cf2fbd24a6c2', 'options', 'IUseCalendarOptions', true, NULL, '', 'Configuration thunks. All fields are getter functions so the composable reacts to reactive sources without re-instantiation. Includes events, view, currentDate, firstDayOfWeek, slotDuration, dayStartHour, dayEndHour, and optional minDate/maxDate/locale.', 0, false, NULL, NULL);
