INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fccb2f2c-d39d-41e3-bb6a-c420deaaffea', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '1962e629-564e-47ab-ac6f-e8d5e174a069', 'props', 'ISizeProps', true, NULL, '', 'Component props extending ISizeProps. Reads the `size` value.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('39b5f0c4-3060-407c-a911-a2888686ffb2', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '1962e629-564e-47ab-ac6f-e8d5e174a069', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the `{name}--size-{value}` class.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b58eb9e6-664e-4b33-b0f2-347071e083a6', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '28906c2e-304e-48b6-af3c-5ac0c01fcb3a', 'props', 'ISliderFieldProps', true, NULL, '', 'Component props. Reads min (default 0), max (default 100), and step (default 0 = no stepping). All three accept string or number — they are parsed with parseFloat internally.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6e302aed-d375-4b44-b236-c7eff1049f79', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '1fba6fe4-1e74-491f-977d-7aac212083bc', 'milliseconds', 'number', true, NULL, '', 'Total countdown duration in milliseconds. This is the initial value of time and the value it resets to on reset().', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c5db3c2c-cdfe-4a2b-905b-fc9003c661e7', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'a17b8f3a-3129-44c4-8ea2-227ee0a16902', 'options', 'IUseSnackbarGroupOptions', false, '{}', '', 'Optional configuration. id (string) namespaces the stack so multiple independent stacks can coexist on the same page (default: SNACKBAR_GROUP_DEFAULT_ID). max (number) caps the stack size with FIFO eviction. defaultDuration (ms) is the fallback auto-dismiss delay for items that omit their own (default: 5000 ms).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b341a908-a091-4eb8-af80-49443cc90d6a', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'd472439c-ce7a-4950-9691-41def7d88bda', 'id', 'MaybeRefOrGetter<string>', false, 'SNACKBAR_GROUP_DEFAULT_ID', NULL, NULL, 0, false, NULL, NULL);
