INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5a0f3e17-a58f-47f1-a514-ab278ba10a96', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'b1f55c3b-edf9-4e1f-a646-2b6726b97f0f', 'options', '{
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7f372638-ddeb-4517-916d-cc362c5e9224', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'fa4929d7-e52e-41ef-ad95-5c0cee91b128', 'isActive', 'Readonly<Ref<boolean>>', true, NULL, '', 'Reactive open/closed state. When it flips to true, useStack registers the component in the global stack and computes a new z-index. When false, the entry is removed and z-index is released.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2a95a8a4-d329-404a-948b-68b0e2aec863', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'fa4929d7-e52e-41ef-ad95-5c0cee91b128', 'zIndex', 'Readonly<Ref<string | number>>', true, NULL, '', 'Base z-index to start from when no other overlays are open. Typically comes from the component props (e.g. zIndex="200").', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d6a79f03-0fc4-4297-8534-ba3ffc519361', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'fa4929d7-e52e-41ef-ad95-5c0cee91b128', 'disableGlobalStack', 'Readonly<Ref<boolean>>', true, NULL, '', 'When true, skips registration in GLOBAL_STACK. Use for overlays that manage their own z-index independently (e.g. nested teleport roots) and should not compete with the global stacking order.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('67110985-97e2-40c0-b6dd-c999d0b0ae0d', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '2fc412d7-3b32-4d7f-bf12-9e1877320ecc', 'props', 'TStateEffectProps', true, NULL, '', 'Component props implementing all eight axes: IColorProps & IBgColorProps & IBorderProps & IRoundedProps & IElevationProps & IPaddingProps & IMarginProps & { gap? }. Also reads props.status when present to force the matching semantic intent (overrides color/bgColor).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('293f873e-1b58-4271-879b-ac4c626d61ff', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '2fc412d7-3b32-4d7f-bf12-9e1877320ecc', 'isHover', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'Reactive hover state from useHover. When true, the composable applies the override values from hoverState for each axis.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d8c11587-0d11-47cb-812b-26145bfff4ef', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'd14e55dc-b90c-479c-b7a8-a99e056d56cf', 'touchless', 'Ref<boolean>', true, NULL, '', 'When true all touch handling is disabled. Lets the consumer disable swipe gestures without unmounting the composable.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('78760048-ae03-4f95-9e7a-3d6692d88a29', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '2fc412d7-3b32-4d7f-bf12-9e1877320ecc', 'isActive', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'Reactive active/selected state from useActive. When true (and isHover is false), override values from activeState are applied. Hover takes priority when both are engaged simultaneously.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5d433217-9e94-4ed4-a972-392af77bddf9', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '2fc412d7-3b32-4d7f-bf12-9e1877320ecc', 'hoverState', 'ComputedRef<IHoverState | undefined>', false, 'computed(() => undefined)', '', 'State config object from useHover. Contains per-axis override values (color, bgColor, border, rounded, elevation, padding, margin, gap) to apply while hovered.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8f4dcae2-f5ff-47da-b568-030e1160c902', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '2fc412d7-3b32-4d7f-bf12-9e1877320ecc', 'activeState', 'ComputedRef<IActiveState | undefined>', false, 'computed(() => undefined)', '', 'State config object from useActive. Same shape as IHoverState — per-axis overrides applied while the item is selected/active.', 4, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6a78f98d-bb4c-4ca4-b5de-3d4ad46a73f2', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '2fc412d7-3b32-4d7f-bf12-9e1877320ecc', 'isDisabled', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'When true, colorClasses is emptied (utility classes suppressed) so the disabled opacity veil is not overridden by a tokenised background.', 5, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('dcd76861-843a-4643-ade4-ccf4dcfe9f62', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '2fc412d7-3b32-4d7f-bf12-9e1877320ecc', 'flat', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'When true, elevationClasses and elevationStyles resolve to empty. Bridges the flat prop of Btn / Card without requiring a separate useElevation call.', 6, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('15d3475e-3954-4912-8947-adc9212214e4', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'c79d2703-c22e-4638-8961-66913e148af4', 'props', 'object', true, NULL, NULL, NULL, 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ba9f3754-971c-4b31-a018-98ead9411bd3', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'c79d2703-c22e-4638-8961-66913e148af4', 'options', 'IStateFlagOptions<S>', true, NULL, NULL, NULL, 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1e5fef8d-49a6-4172-b40a-c6c00e7a47f3', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '399d9669-d273-466f-b0ae-ec02d2277360', 'props', 'IStatusProps & IAdjacentProps', true, NULL, '', 'Component props. Reads status (TStatus: success | info | warning | error), statusIconPosition (prepend | append | both | replace), prependIcon, appendIcon, and icon. When status is set and statusIconPosition is replace, the status icon overwrites props.icon; when prepend/append/both, it fills the matching slot only if no explicit icon prop was passed.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('676d69d8-1216-416d-800f-055cf400723d', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '399d9669-d273-466f-b0ae-ec02d2277360', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name used to build the BEM modifier class `{name}--{status}` (e.g. origam-alert--success). Defaults to the current Vue instance name.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a4303474-60b9-438c-88e3-974ae69d8c18', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '258f3bc4-0fc7-4430-81b4-c9848a1ef163', 'rootEl', 'Ref<HTMLElement | undefined>', true, NULL, NULL, NULL, 0, false, NULL, NULL);
