INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('43651f2e-7b9e-4180-af42-e55c463628b5', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '258f3bc4-0fc7-4430-81b4-c9848a1ef163', 'layoutItemStyles', 'Ref<CSSProperties>', true, NULL, NULL, NULL, 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('20f77473-1d32-4c09-93b5-dd248f6563fb', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '00da01b4-d0bf-4975-8ddb-c8a40865604a', 'styles', 'ComputedRef', true, NULL, '', 'A ComputedRef returning a CSS value array or object. Accepts the same formats as Vue :style bindings (array of objects, strings, or mixed). useStyle normalises this to a flat `#id { prop: value; … }` string and feeds it to useStyleTag.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('aeebb4d9-b873-4afc-a8f6-7bb1311d15f1', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '00da01b4-d0bf-4975-8ddb-c8a40865604a', 'uniq', 'MaybeRefOrGetter<string | undefined>', false, 'undefined', '', 'Optional fixed element id. When omitted, a unique id is generated from the component name and a counter (e.g. origam-card-3). Provide a fixed id when multiple instances must share the same <style> tag (e.g. global animation keyframes).', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('01ea3cf5-b80e-4e85-a952-300554809b1a', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '00da01b4-d0bf-4975-8ddb-c8a40865604a', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the generated id. Defaults to the current Vue instance name.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3172bb5a-1b9c-46d1-8b36-bf1766fdfe0e', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '82ccb5a0-5ca0-4428-9d54-375f8c717809', 'css', 'MaybeRef<string>', true, NULL, NULL, NULL, 0, false, NULL, NULL);
