INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('02b7b75b-ee0c-4013-a175-5d8fda55aaa2', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'dda32fd3-6a21-4cd4-9734-60056f253ffe', 'target', 'Ref<boolean | string | Element>', true, NULL, '', 'Reactive teleport destination. true → returns undefined (Vue Teleport disabled, renders in-place). false → document.body. A CSS selector string → querySelector result. An Element → used directly. Returns undefined and warns if a string selector yields no match.', 0, false, NULL, NULL);
