INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a232126e-c61e-4aec-8a44-769f4484c126', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'de3b655c-688a-4a65-981c-a1ca51e28658', 'name', 'K', false, NULL, '', 'The key to read from the props object. Typically "color". Omit when passing a plain Ref.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7b302631-7108-4c52-8d7b-d203d6f4af03', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '3aa6ed1d-af36-4079-b205-85168e72513d', 'fn', '(...args: T) => R', true, NULL, '', 'The function to throttle. Called immediately on the first invocation within each window. The return value is discarded — the wrapper always returns void.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('946abe07-d4a7-4ac8-bfab-d743eafd82c8', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '3aa6ed1d-af36-4079-b205-85168e72513d', 'wait', 'number', true, NULL, '', 'Throttle window in milliseconds. No call will execute within wait ms of the previous execution.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3d9a668b-bb87-45b5-b9af-a78151abbf6f', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '9e981cec-01a6-4c47-a1f0-027167cb1920', 'source', 'WatchSource<boolean>', true, NULL, '', 'Reactive boolean source (ref, computed, or getter). When it evaluates to true the scope is started; when false the scope is stopped.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2496a0ea-58b6-4399-ba37-e2c712e85bce', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '9e981cec-01a6-4c47-a1f0-027167cb1920', 'fn', '(reset: () => void) => void', true, NULL, '', 'Callback run inside the new effectScope. Receives a `reset()` function that can be called from inside the scope to stop the current scope and immediately restart it — useful for subscriptions that need to re-initialise when an inner condition changes.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2daa8eb1-3a87-4dc1-bc18-eaef112b0b48', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'd14e55dc-b90c-479c-b7a8-a99e056d56cf', 'isActive', 'Ref<boolean>', true, NULL, '', 'Whether the drawer is currently open. The composable writes to this ref when a fling gesture settles.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('612bc85f-45e4-4620-84d0-da4f50c7fdf4', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'd14e55dc-b90c-479c-b7a8-a99e056d56cf', 'isTemporary', 'Ref<boolean>', true, NULL, '', 'When true the drawer is temporary (modal overlay). The touch zone logic also activates for touches anywhere inside the element body, not only at the edge.', 1, false, NULL, NULL);
