INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7c46b026-eabd-4355-8b79-84566e708ac3', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'f7149be2-f10b-4542-8bdf-14a9f2dc0b71', 'props', 'IVirtualProps', true, NULL, '', 'Reads `itemHeight` (expected row height in px, used to estimate the initial window), `height` (container height as string / number), `scrollDuration` (ms, default 300), `scrollEasing` (easing name, default easeInOutCubic).', 0, false, NULL, NULL);
