INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('63ec8b6d-a878-4a16-b88c-48f292a972a9', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'f84bea9d-b158-4d99-9115-fdef33d1a687', 'type', 'string', NULL, NULL, true, false, NULL, NULL, 'MIME type — video/mp4, video/webm, application/vnd.apple.mpegurl for HLS. Recommended: lets the browser skip sources it cannot decode without a network round-trip.', 1, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2d4d8a7e-9797-44e5-957e-8659b3eee859', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'f84bea9d-b158-4d99-9115-fdef33d1a687', 'quality', 'string', NULL, NULL, true, false, NULL, NULL, 'Quality identifier used to group multiple sources of the same content at different resolutions (e.g. "1080p", "720p", "auto"). When two or more sources expose distinct quality values, OrigamVideo shows a Quality entry in the settings menu.', 2, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8ea0ea63-148d-4790-a331-4641819fbf55', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'f84bea9d-b158-4d99-9115-fdef33d1a687', 'label', 'string', NULL, NULL, true, false, NULL, NULL, 'Optional human-readable label override for the quality switcher menu. Defaults to the quality value when not provided.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f6dea137-b2d0-4fdb-a2c6-9c245e6f0410', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '83f9aae7-2472-4334-955d-7a7d614bac69', 'kind', 'TVideoTrackKind', NULL, NULL, false, false, NULL, NULL, 'Kind of the track. captions is the default — used by the built-in captions switcher. subtitles is treated the same way; descriptions and chapters are declared but not surfaced in the default toolbar.', 0, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8ff2e045-1bca-4244-a51b-db5de7bb5156', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '83f9aae7-2472-4334-955d-7a7d614bac69', 'src', 'string', NULL, NULL, false, false, NULL, NULL, 'URL of the WebVTT file. Same-origin or CORS-enabled, otherwise the browser silently rejects the track.', 1, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('99d16c19-5da7-4c3e-8306-fcf41b18553e', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '83f9aae7-2472-4334-955d-7a7d614bac69', 'srclang', 'string', NULL, NULL, false, false, NULL, NULL, 'BCP-47 language tag — "en", "fr", "pt-BR". Drives the language label in the captions switcher and is exposed to assistive technology via the underlying <track srclang>.', 2, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('539d3177-4a0e-4023-899c-e6502f750a4f', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '83f9aae7-2472-4334-955d-7a7d614bac69', 'label', 'string', NULL, NULL, true, false, NULL, NULL, 'Human-readable label shown in the switcher ("English", "Francais"). Defaults to the uppercased srclang when omitted.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('093b3bf2-ab52-4cbe-b3a2-2606167d4eee', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '83f9aae7-2472-4334-955d-7a7d614bac69', 'default', 'boolean', NULL, NULL, true, false, NULL, NULL, 'Marks this track as the one to enable on load. At most one track per kind should be flagged — if multiple are passed, the first one wins.', 4, false, NULL, NULL);
