INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('37a4267c-0909-4426-9043-36709f0bd476', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '5844104f-b110-42c2-a028-a1e849169d06', 'format', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.format.description', 'Auto-format the code before highlighting. Reserved — currently a no-op that warns in dev mode. Prettier is not bundled at runtime to keep the tarball small.', 5, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('792515c2-b8ac-4c94-be67-fb5516b29ebe', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '5844104f-b110-42c2-a028-a1e849169d06', 'wrap', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.wrap.description', 'Wraps long lines instead of scrolling horizontally.', 6, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6dd4b10e-8ca7-444b-b4b8-83f1fbd28d9b', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '5844104f-b110-42c2-a028-a1e849169d06', 'filename', 'string', '', 'primitive', NULL, false, 'undefined', 'components.code.props.filename.description', 'Optional filename rendered in the header bar (e.g. ''App.vue''). When present AND copyable=true, the header hosts the copy button; otherwise the copy button floats in the top-right corner.', 7, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('dd374b85-71a2-4195-a869-00ae83d2c46a', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '5844104f-b110-42c2-a028-a1e849169d06', 'marginTop', 'boolean | number | string', NULL, NULL, NULL, false, NULL, NULL, NULL, 60, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('073d4c9f-de60-46c0-bed7-e041fa534b70', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '5844104f-b110-42c2-a028-a1e849169d06', 'compact', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.compact.description', 'Renders as a single-line inline pill (ideal for install commands). Header, filename and line numbers are suppressed; the copy button collapses to a small icon.', 8, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d13f8163-c9be-49e9-a0e4-39ed09892ede', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '5844104f-b110-42c2-a028-a1e849169d06', 'prompt', 'string', '', 'primitive', NULL, false, 'undefined', 'components.code.props.prompt.description', 'Decorative prefix rendered before the code (e.g. ''$'' for shell commands). Purely visual — not copied to clipboard.', 9, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9855cb2a-7816-490b-9f1b-305f4783c7bc', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '5844104f-b110-42c2-a028-a1e849169d06', 'hideHeader', 'boolean', NULL, NULL, NULL, false, NULL, NULL, 'Do not render the header bar (filename / language badge / copy button). For a block embedded in a surface that already shows that information, such as a tab of OrigamCodeGroup.', 10, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ec0f1e99-f884-4c57-a532-e6aea046df6a', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '5844104f-b110-42c2-a028-a1e849169d06', 'flat', 'boolean', NULL, NULL, NULL, false, NULL, NULL, 'Flatten the block into its host: no border, no radius, no elevation, no outer margin.', 11, false, NULL, NULL);
