INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d17a63eb-d8eb-470b-b38b-cd6d1e34d4ae', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '92e917e2-484b-4b5b-8692-c5b4cf92ba3a', 'state', 'IMediaPlayerState', '', 'primitive', NULL, true, '—', 'components.media_controller.props.state.description', 'Reactive media state from useMediaPlayer() (or a specialisation: useVideoPlayer, useAudioPlayer). Contains refs for playing, currentTime, duration, volume, muted, buffered, playbackRate, remoteAvailable, remoteState.', 0, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('87875adc-e14d-4cd7-b6f1-b860853c3725', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '92e917e2-484b-4b5b-8692-c5b4cf92ba3a', 'methods', 'IMediaPlayerMethods', '', 'primitive', NULL, true, '—', 'components.media_controller.props.methods.description', 'Imperative methods from useMediaPlayer(). Provides play(), pause(), seek(), setVolume(), toggleMute(), setPlaybackRate(), requestRemotePlayback().', 1, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('540fbe55-9d55-4b67-8143-ec6eccabbb8a', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '92e917e2-484b-4b5b-8692-c5b4cf92ba3a', 'inset', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.inset.description', 'YouTube-style overlay mode: the shell sits on top of the media surface with a dark gradient and auto-hides on visible=false. When false, renders as a regular always-on toolbar.', 2, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bc9d9a63-91ff-4eee-b816-0592e4e60251', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '92e917e2-484b-4b5b-8692-c5b4cf92ba3a', 'visible', 'boolean', '', 'primitive', NULL, false, 'true', 'components.media_controller.props.visible.description', 'Visibility flag driven by the parent autohide logic. Only meaningful when inset=true. When false, the shell is opacity: 0 and pointer-events: none.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('aa4d1da8-9139-4f81-8902-a908705845ca', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '92e917e2-484b-4b5b-8692-c5b4cf92ba3a', 'playbackRates', 'ReadonlyArray<number>', '', 'primitive', NULL, false, '[0.5, 0.75, 1, 1.25, 1.5, 2]', 'components.media_controller.props.playback_rates.description', 'Available playback rates exposed via the config cog menu. When the array has more than 1 entry, a "Playback speed" drill-down appears.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8ab45e23-af29-4186-b944-4056fb38f504', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '92e917e2-484b-4b5b-8692-c5b4cf92ba3a', 'allowRemotePlayback', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.allow_remote_playback.description', 'Enable the Cast / AirPlay button (Remote Playback API). The button only appears when this flag is true AND state.remoteAvailable is true at runtime.', 5, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('23f658f5-fc15-49f9-8678-808fb11f815b', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '92e917e2-484b-4b5b-8692-c5b4cf92ba3a', 'downloadable', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.downloadable.description', 'Adds a "Download" row to the config cog menu when true. Requires downloadUrl to be set.', 6, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0eb62cc7-7e64-487e-ab04-c2dc5ee78380', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '92e917e2-484b-4b5b-8692-c5b4cf92ba3a', 'downloadUrl', 'string | null', '', 'primitive', NULL, false, 'null', 'components.media_controller.props.download_url.description', 'URL surfaced to the consumer when the Download menu item is clicked. Supports same-origin, data: and blob: URLs natively; cross-origin URLs are routed through a fetch → blob pipeline.', 7, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b09db351-321f-4879-83ae-e8c39c489d73', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '1aa6164e-e378-438f-9fe6-6298d81b3f72', 'roundedTopRight', 'boolean | number | string', NULL, NULL, NULL, false, NULL, NULL, NULL, 18, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('41ec2142-252f-440e-9cd9-4fbbe068c3e3', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '92e917e2-484b-4b5b-8692-c5b4cf92ba3a', 'downloadFilename', 'string', '', 'primitive', NULL, false, 'undefined', 'components.media_controller.props.download_filename.description', 'Suggested filename for the downloaded file (<a download="…"> attribute).', 8, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f17a86f2-c3aa-4449-aaea-ae32959f2e83', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '92e917e2-484b-4b5b-8692-c5b4cf92ba3a', 'qualityOptions', 'ReadonlyArray<TQualityOption>', '', 'primitive', NULL, false, '[]', 'components.media_controller.props.quality_options.description', 'Optional list of quality variants. When ≥ 2 entries are present, a "Quality" drill-down appears in the config menu. Each entry is { quality: string; label: string }.', 9, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('277ca43b-e0a3-44d0-8e6d-98307e08a519', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '92e917e2-484b-4b5b-8692-c5b4cf92ba3a', 'currentQuality', 'string | null', '', 'primitive', NULL, false, 'null', 'components.media_controller.props.current_quality.description', 'Currently-active quality identifier displayed as the appendText in the Quality menu row.', 10, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3a85dc22-d199-443a-9e7a-90b808728693', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '92e917e2-484b-4b5b-8692-c5b4cf92ba3a', 'showPrevious', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.show_previous.description', 'Show the "previous track" transport button. The parent listens to the previous emit and decides the action (skip back 10s or jump to the previous playlist track).', 11, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0d393845-965b-4a83-8abe-d8929a488263', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '92e917e2-484b-4b5b-8692-c5b4cf92ba3a', 'showNext', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.show_next.description', 'Show the "next track" transport button. The parent owns the action.', 12, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1cd4d355-fc0e-4b3b-9bf0-c191670e88d9', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '92e917e2-484b-4b5b-8692-c5b4cf92ba3a', 'showLoop', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.show_loop.description', 'Show the tri-state loop button (none → all → one → none). Supports v-model:loopMode.', 13, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('547dfb37-469b-4690-91bb-0b5b542dc967', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '92e917e2-484b-4b5b-8692-c5b4cf92ba3a', 'showShuffle', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.show_shuffle.description', 'Show the shuffle toggle button. Supports v-model:shuffle.', 14, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('920bb467-7af7-42a7-abdd-f2a14609645a', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '92e917e2-484b-4b5b-8692-c5b4cf92ba3a', 'loopMode', 'TAudioLoopMode', '', 'primitive', NULL, false, '''none''', 'components.media_controller.props.loop_mode.description', 'Current loop mode: "none" | "all" | "one". The Controller cycles on click and emits update:loopMode; the parent applies its playlist or <audio loop> policy.', 15, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0548896a-c33b-4f54-96f8-53e18b06801b', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '92e917e2-484b-4b5b-8692-c5b4cf92ba3a', 'shuffle', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.shuffle.description', 'Current shuffle state. The Controller toggles on click and emits update:shuffle; the parent switches its next-track resolution.', 16, false, NULL, NULL);
