INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0548cd8a-37f6-48a8-bdaf-9d26e75ba1c2', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '1aa6164e-e378-438f-9fe6-6298d81b3f72', 'modelValue', 'number', '', 'primitive', NULL, true, '—', 'components.media_scrubber.props.model_value.description', 'Current value between min and max. Supports v-model. The component never mutates this directly — every change surfaces via update:modelValue.', 0, false, NULL, NULL);
