INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1d33486e-4c8b-43cf-ac7f-fd5d087ec030', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '1aa6164e-e378-438f-9fe6-6298d81b3f72', 'step', 'number', '', 'primitive', NULL, false, '0', 'components.media_scrubber.props.step.description', 'Discrete step. 0 (default) means continuous — pointer events emit the raw float; positive values snap each emission to the nearest multiple.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3cd0aed1-c9f6-4df0-ba66-3d333217e711', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '1aa6164e-e378-438f-9fe6-6298d81b3f72', 'buffered', 'number', '', 'primitive', NULL, false, 'undefined', 'components.media_scrubber.props.buffered.description', 'Optional buffered position (end of the browser''s media buffer). Renders the __buffer bar from min up to buffered. Pass undefined to hide the bar entirely.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1211d236-2464-46ed-ab0f-b4bffb1bef0f', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '1aa6164e-e378-438f-9fe6-6298d81b3f72', 'orientation', 'TMediaScrubberOrientation', '', 'primitive', NULL, false, '''horizontal''', 'components.media_scrubber.props.orientation.description', 'Layout axis. horizontal = YouTube timeline shape; vertical = volume / level meter shape (top of track = max, bottom = min).', 5, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ea8b154e-002e-44fc-8d50-51d12f18eb21', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '1aa6164e-e378-438f-9fe6-6298d81b3f72', 'disabled', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_scrubber.props.disabled.description', 'Disables pointer + keyboard interaction. The element drops out of the tab order (tabindex="-1") and pointer events become no-ops.', 6, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ecae6f60-da62-4216-a5aa-01535ec76316', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '1aa6164e-e378-438f-9fe6-6298d81b3f72', 'showThumbOnHoverOnly', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_scrubber.props.show_thumb_on_hover_only.description', 'Hides the thumb at rest and reveals it on hover / focus / drag — the YouTube pattern. When false, the thumb is always visible.', 7, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('351196b9-dbbd-4c69-98af-d9082b833599', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:36:26.857414+00', '1aa6164e-e378-438f-9fe6-6298d81b3f72', 'showHoverTooltip', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_scrubber.props.show_hover_tooltip.description', 'Shows a tooltip above the cursor (horizontal only) reflecting the hovered value. Content can be overridden via the #tooltip slot.', 8, false, NULL, NULL);
