INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9c69bc30-e88e-40a8-a8c1-d5247ee3197f', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'fa49ef84-73b8-4641-9d1f-cf2fbd24a6c2', 'helpers', 'object', '', 'Re-exported date utility functions (isSameDay, isSameMonth, startOfDay, startOfMonth, endOfMonth, addDays, addMonths, addWeeks, diffMinutes, toDate). Exposed so consumers can extend calendar UIs without a separate import.', 9, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8a1f8e45-80ef-429f-9e28-948d3aed9757', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'd81ca273-27f6-42cb-8e40-5897d15d7974', 'getPadding', '(column: IInternalDataTableHeader) => string | undefined', '', 'Returns a padding shorthand string for the given column. Returns "0 8" for the built-in select/expand columns, the column''s own padding value when defined, or undefined to fall back to CSS token-driven spacing.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c7553ffe-9f4b-42d5-b2df-43ad7ed8d54c', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '7dc90ca3-cb88-4b3c-a805-cb6a1d8b6490', 'viewBox', 'ComputedRef<string>', '', 'Pre-formatted SVG viewBox attribute string ("0 0 W H"). The chart always renders at its full logical size; CSS handles visual scaling.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d35f581e-3c3f-41da-8656-28452a82924e', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '7dc90ca3-cb88-4b3c-a805-cb6a1d8b6490', 'scales', 'ComputedRef<IChartScales>', '', 'Pixel-mapping functions: scales.x(value, dataIndex?, categoryCount?) and scales.y(value). Clamp values to the plot bounds so out-of-range data stays inside the SVG frame.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2a911cc9-5f08-4ccb-a7b5-64c32c266859', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '7dc90ca3-cb88-4b3c-a805-cb6a1d8b6490', 'ticks', 'ComputedRef<{ x: Array<IChartTick>; y: Array<IChartTick> }>', '', 'Gridline and axis-label descriptors for both axes. Bar charts swap the axis roles automatically (categorical along Y, value along X).', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f931cb03-9b1f-472e-96a2-5c0dd97e9749', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '7dc90ca3-cb88-4b3c-a805-cb6a1d8b6490', 'secondaryTicks', 'ComputedRef<Array<IChartTick>>', '', 'Tick descriptors for the optional right-hand Y axis. Populated only when secondaryYAxis is configured or a series carries yAxis === 1.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0932967d-bb42-49db-8767-c06c4d42a647', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '7dc90ca3-cb88-4b3c-a805-cb6a1d8b6490', 'paths', 'ComputedRef<Array<IChartPath>>', '', 'Per-series render descriptors: path (line/area/pie/radar/polygon), rect (bar/column), or circle (scatter/markers). One entry per series for most types, one per data point for bar and scatter.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0a5b6e34-fe68-462a-ac8e-9780321fe609', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '7dc90ca3-cb88-4b3c-a805-cb6a1d8b6490', 'legend', 'ComputedRef<Array<IChartLegendItem>>', '', 'Pre-resolved legend entries. Single-series pie/donut exposes one entry per slice (category); all other types expose one entry per series.', 5, false, NULL, NULL);
