INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d092cf7c-b00f-4085-b992-fa183f33ae1e', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '58719e2b-2c22-455b-acff-bec0eeb06045', 'currentSnap', 'Ref<TSheetSnapId>', '', 'The id of the currently active snap point. Writable — programmatically call snapTo() or assign directly. Kept in sync with options.defaultSnap via a watcher.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('73578eac-9142-49d7-beda-6628dd5c5810', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '58719e2b-2c22-455b-acff-bec0eeb06045', 'dragOffset', 'ShallowRef<number>', '', 'Live pixel offset from the baseline snap height during an active drag. Positive = sheet growing (finger moving up). Resets to 0 on pointer release. Bind to a CSS translateY to achieve 1:1 finger tracking.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('992f67a0-1170-4afa-b991-ef6b9756dd9b', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '58719e2b-2c22-455b-acff-bec0eeb06045', 'isDragging', 'ShallowRef<boolean>', '', 'True while a pointer is captured by the handle. Use it to suppress the sheet transition (transition: none) so the user sees immediate 1:1 tracking instead of the animated snap.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d2a025f0-d3a0-4a90-a6bd-2a324ce6499a', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '58719e2b-2c22-455b-acff-bec0eeb06045', 'snapTo', '(id: TSheetSnapId) => void', '', 'Programmatically move to a named snap point. Respects the persistent constraint (cannot snap to closed when persistent=true). Resets dragOffset to 0.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7a5f1c03-5bd0-4cfd-94a9-1dd647d021ac', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '58719e2b-2c22-455b-acff-bec0eeb06045', 'dismiss', '() => void', '', 'Convenience wrapper for snapTo("closed"). Blocked when persistent=true (falls back to the lowest non-zero snap).', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c8abec62-ec4d-426a-8a23-c0dc74be04e1', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '58719e2b-2c22-455b-acff-bec0eeb06045', 'currentSnapHeight', 'ComputedRef<number>', '', 'Resolved pixel height of the current snap point. SSR-safe (returns 0 when window is absent). Used to compute the sheet height style: currentSnapHeight + dragOffset.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c91995ea-eae8-4090-b64b-17f5886fcbbb', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '1962e629-564e-47ab-ac6f-e8d5e174a069', 'sizeClasses', 'ComputedRef<string[]>', '', 'Component-local BEM modifier class (e.g. "origam-btn--size-small") plus the typographic utility class (e.g. "origam--text-sm") bridging the legacy to modern taxonomy.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5a282432-1199-4066-9657-7a229e1ded86', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '1962e629-564e-47ab-ac6f-e8d5e174a069', 'sizeStyles', 'ComputedRef<string[]>', '', 'Inline width and height declarations for custom numeric or CSS-length sizes (when the value is not a named preset).', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1f4b5500-dea7-4d2e-8e45-63be83af3476', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '28906c2e-304e-48b6-af3c-5ac0c01fcb3a', 'min', 'ComputedRef<number>', '', 'Parsed minimum value. Defaults to 0 when props.min is undefined or null.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('24df9f72-2820-461a-9f1c-92164598c313', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '28906c2e-304e-48b6-af3c-5ac0c01fcb3a', 'max', 'ComputedRef<number>', '', 'Parsed maximum value. Defaults to 100 when props.max is undefined or null.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5e46688a-b1d4-4ff7-a0cd-47e41f8ba56c', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '28906c2e-304e-48b6-af3c-5ac0c01fcb3a', 'step', 'ComputedRef<number>', '', 'Parsed step value. 0 means no stepping (any value between min and max is valid). Positive values define the snap grid.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ed51cac5-e0a0-4759-a05a-ddc92723aedd', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '28906c2e-304e-48b6-af3c-5ac0c01fcb3a', 'decimals', 'ComputedRef<number>', '', 'Number of decimal places to preserve in roundValue output. Derived from max(getDecimals(step), getDecimals(min)) to match the precision implied by the step grid.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('52a17c71-d4fa-4266-8618-f457a70b625d', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '28906c2e-304e-48b6-af3c-5ac0c01fcb3a', 'roundValue', '(value: string | number) => number', '', 'Snap a raw value to the nearest valid step, clamped to [min, max]. Handles the min-offset edge case so that a step=5 min=3 grid snaps to 3, 8, 13, … rather than 0, 5, 10, ….', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('66398b0b-169a-4a70-a0d8-78ccb24e5c42', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '1fba6fe4-1e74-491f-977d-7aac212083bc', 'time', 'ShallowRef<number>', '', 'Remaining milliseconds. Starts at the initial milliseconds value, decrements on each tick, and bottoms out at 0. Bind to a progress bar width to visualise the countdown.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1062dd7b-8c8c-47eb-818a-b2e44a82cd6f', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '1fba6fe4-1e74-491f-977d-7aac212083bc', 'clear', '() => void', '', 'Stops the interval without resetting time. Use to pause the countdown (e.g. while the user is hovering the snackbar).', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('187a9f93-b407-495c-a4a4-f56a0c20b3ca', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '1fba6fe4-1e74-491f-977d-7aac212083bc', 'reset', '() => void', '', 'Clears the interval and resets time to the initial milliseconds value on the next tick. Use when the snackbar content changes and the countdown should restart.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5351e308-9341-4ac8-b9b3-f5577197e4aa', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '1fba6fe4-1e74-491f-977d-7aac212083bc', 'start', '(el?: HTMLElement) => void', '', 'Start (or resume) the countdown. Reads the CSS transitionDuration of el to synchronise tick frequency with the progress bar animation. Falls back to 200 ms when no element is provided or no transition is set. Clears any existing interval before starting.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('eb6a6e15-1284-426c-a545-caaade31f586', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'a17b8f3a-3129-44c4-8ea2-227ee0a16902', 'items', 'Readonly<Ref<ReadonlyArray<ISnackbarGroupItem>>>', '', 'Reactive read-only snapshot of the current stack. Mutate only through notify / dismiss / dismissAll — direct writes are blocked at the TypeScript level.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b9051abb-6976-4354-a7a2-bb6ba5990dc4', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'a17b8f3a-3129-44c4-8ea2-227ee0a16902', 'notify', '(opts: ISnackbarGroupItemOptions) => string', '', 'Push a new item onto the stack. Accepts ISnackbarGroupItemOptions (message, variant, icon, duration, onDismiss callback…). Returns the generated item id so the caller can dismiss it early.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0a124ed0-0a9b-4e78-8e5b-b8185c2a8739', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'a17b8f3a-3129-44c4-8ea2-227ee0a16902', 'dismiss', '(itemId: string) => void', '', 'Remove the item with the given id from the stack, cancel its auto-dismiss timer, and invoke its onDismiss callback if any.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bb83fc33-95a7-45d4-8405-c209993cae25', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'a17b8f3a-3129-44c4-8ea2-227ee0a16902', 'dismissAll', '() => void', '', 'Dismiss every item in the stack in one call. Iterates a snapshot of the ids so mid-loop mutations are safe.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('00f5f082-7266-47eb-94aa-efd52f9a9ca4', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '5be270d5-b8f4-410e-b6d2-7e6be067fc67', 'sortBy', 'Ref<Array<IDataTableSortItem>>', '', 'Reactive array of active sort descriptors, each with a key (column key) and an order (asc | desc). Driven by useVModel against the host table props.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('98e63368-47d3-4e1e-b617-e3e62edac03a', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '5be270d5-b8f4-410e-b6d2-7e6be067fc67', 'toggleSort', '(column: IInternalDataTableHeader) => void', '', 'Cycle the sort state for a column: none → asc → desc → none (or asc when mustSort=true). Respects multiSort — when false, replaces the entire sortBy array with a single entry.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4016e63d-e4f4-4cf1-b87b-17a5994c09b9', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '5be270d5-b8f4-410e-b6d2-7e6be067fc67', 'isSorted', '(column: IInternalDataTableHeader) => boolean', '', 'Returns true when the column has an active sort entry in sortBy. Used by header cells to show the sort icon.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d26768fa-4503-43c2-a976-39228a28f4cd', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'd44e03fe-6683-4a6e-8e2a-ddc117d6ffe2', 'ssrBootStyles', 'ComputedRef<CSSProperties | []>', '', 'An object `{ transition: "none !important" }` when the component has not yet booted, or an empty array after the first animation frame. Spread onto the root element via :style to suppress hydration-flash transitions.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7636e5a5-846f-4a0a-804d-f21aaf87f032', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'd44e03fe-6683-4a6e-8e2a-ddc117d6ffe2', 'isBooted', 'Readonly<ShallowRef<boolean>>', '', 'False on the server and during the first rAF after mount, true thereafter. Useful as a guard before running DOM-dependent logic that assumes the component is fully hydrated.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8c7d3d95-5f57-41a0-85ee-7479cef04841', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '4e1b40ef-e717-4fb4-aad1-6504d7e315ad', NULL, 'number', 'utils.detail.apc_acontrast.returns', 'Signed APCA contrast value. Absolute value >= 45 is the recommended minimum for body text.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f4782c49-359a-437d-bdbd-493a6e3c17d8', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'fa4929d7-e52e-41ef-ad95-5c0cee91b128', 'globalTop', 'Readonly<ShallowRef<boolean>>', '', 'True when this component is the last entry in GLOBAL_STACK (topmost overlay on the page). Updated asynchronously via setTimeout to avoid synchronous circular reads during stack registration.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('df1d63fe-73b5-4a89-b8fe-e2a0502e062f', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'fa4929d7-e52e-41ef-ad95-5c0cee91b128', 'localTop', 'ComputedRef<boolean>', '', 'True when this overlay has no active child overlays (nothing opened on top of it within its own sub-tree). Used to decide whether clicks on the backdrop should close this overlay.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e2c91f33-3455-4977-8bb8-f842517594a5', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'fa4929d7-e52e-41ef-ad95-5c0cee91b128', 'stackStyles', 'ComputedRef<{ zIndex: number }>', '', 'Style object containing the computed zIndex. Spread onto the overlay root element so it automatically rises above the previous topmost overlay.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('35363d04-3e43-48ea-8ad5-b14246113200', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '2fc412d7-3b32-4d7f-bf12-9e1877320ecc', 'colorClasses / colorStyles', 'ComputedRef<string[]>', '', 'Tokenised intent values emit a utility class (origam--bg-primary); custom CSS colors emit an inline style. Both are empty when disabled/hover/active is true (state-inline path takes over).', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c0f18331-721f-4f5d-9071-8d9c91e51ec2', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '2fc412d7-3b32-4d7f-bf12-9e1877320ecc', 'borderClasses / borderStyles', 'ComputedRef<string[]>', '', 'Delegated to useBorder with a reactive proxy that swaps to hoverState/activeState.border when the state is engaged.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f36320fa-6b4b-4ff3-88da-42af6776f8df', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '2fc412d7-3b32-4d7f-bf12-9e1877320ecc', 'roundedClasses / roundedStyles', 'ComputedRef<string[]>', '', 'Delegated to useRounded. State-aware: applies hoverState/activeState.rounded when engaged.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d38d62da-2cb5-412c-bf3b-d6ca0add497c', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '2fc412d7-3b32-4d7f-bf12-9e1877320ecc', 'elevationClasses / elevationStyles', 'ComputedRef<string[]>', '', 'Delegated to useElevation. Cleared when flat=true. State-aware via the pickEffective resolver.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6267c5e9-bd9a-4db6-8a9a-f48d4e2ec289', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '2fc412d7-3b32-4d7f-bf12-9e1877320ecc', 'paddingClasses / paddingStyles', 'ComputedRef<string[]>', '', 'Delegated to usePadding via a reactive getter proxy to preserve dependency tracking across state swaps.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('12f0a3f0-08df-45c5-8fd5-303bab59122e', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '2fc412d7-3b32-4d7f-bf12-9e1877320ecc', 'marginClasses / marginStyles', 'ComputedRef<string[]>', '', 'Delegated to useMargin via a reactive getter proxy.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('42ae59be-f005-43e0-884b-6f4c235d02cc', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '2fc412d7-3b32-4d7f-bf12-9e1877320ecc', 'gapClasses / gapStyles', 'ComputedRef<string[]>', '', 'Gap has no dedicated composable. Emits an inline style (gap: Npx or gap: <value>) when a gap override is present. gapClasses is always empty.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2f666a36-7553-4bc2-ac1f-e23bd2c2199a', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '399d9669-d273-466f-b0ae-ec02d2277360', 'icon', 'ComputedRef<string | undefined>', '', 'Resolved center/replace icon. Returns the status icon when statusIconPosition="replace" and no explicit props.icon was provided, otherwise passes through props.icon.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4f9f5acf-b08d-495f-b5db-5c32fbb6fb5f', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '399d9669-d273-466f-b0ae-ec02d2277360', 'prependIcon', 'ComputedRef<string | undefined>', '', 'Resolved prepend-slot icon. Injects the status icon when statusIconPosition is prepend or both and props.prependIcon is unset.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5afe534c-d8a4-42c0-8e9b-a59860535515', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '399d9669-d273-466f-b0ae-ec02d2277360', 'appendIcon', 'ComputedRef<string | undefined>', '', 'Resolved append-slot icon. Injects the status icon when statusIconPosition is append or both and props.appendIcon is unset.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('75086fe4-0f02-483d-b225-523623914027', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '399d9669-d273-466f-b0ae-ec02d2277360', 'statusClasses', 'ComputedRef<string[]>', '', 'Array containing `{name}--{status}` when a status is set, empty otherwise. Bind to the root element for SCSS state selectors.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fd674fb2-5f58-42d9-ac61-7e7313a1185f', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '399d9669-d273-466f-b0ae-ec02d2277360', 'statusIntent', 'ComputedRef<TColor | undefined>', '', 'The resolved TColor intent for the current status (success→success, info→info, warning→warning, error→danger). Undefined when no status is set. Consumed by useStateEffect to force the semantic surface color.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('76a11f73-a0fa-428a-85a3-b21209845043', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '258f3bc4-0fc7-4430-81b4-c9848a1ef163', 'isStuck', 'ShallowRef<boolean | "top" | "bottom">', '', 'Current stuck state. "top" = anchored at the top of the viewport (sidebar shorter than viewport or scrolled to top), "bottom" = anchored at the bottom edge, true = stuck mid-page (sidebar taller than viewport, user scrolled past the top edge), false = not sticky (isSticky prop is false).', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b6656cd7-e0b1-40a6-b07d-a6199a66349d', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '258f3bc4-0fc7-4430-81b4-c9848a1ef163', 'stickyStyles', 'ComputedRef<Array<CSSProperties | undefined>>', '', 'Two-element style array to spread on the element. The first resets top/bottom/height when isSticky is enabled. The second applies the computed positional offset: the layoutItem top when not yet stuck, or the scrolled stuckPosition when stuck mid-page or at the bottom.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2585f55b-f118-4ba1-a91d-ea69e39cb089', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '00da01b4-d0bf-4975-8ddb-c8a40865604a', 'id', 'ComputedRef<string>', '', 'The element id used as the CSS scope selector (#id). Apply this id to the root element of the component so the injected styles target only this instance.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a7e755e0-ddd6-4997-b8b2-918e7fe53b13', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '00da01b4-d0bf-4975-8ddb-c8a40865604a', 'css', 'ShallowRef<string>', '', 'The current generated CSS string. Reactive — updates whenever the styles ComputedRef changes.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8430dd0e-0ffa-46e0-ac2e-22a69b386d4e', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '00da01b4-d0bf-4975-8ddb-c8a40865604a', 'load / unload', '() => void', '', 'Manually control style tag injection. Normally called automatically on mount / scope dispose. Call load() to re-inject after an explicit unload().', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('70fe022b-78c2-4e5a-9c0d-b637df990313', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '00da01b4-d0bf-4975-8ddb-c8a40865604a', 'isLoaded', 'Readonly<ShallowRef<boolean>>', '', 'True when the <style> tag is currently present in document.head.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5bbf5123-e3df-4f4d-b8c9-4490043677f8', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'dda32fd3-6a21-4cd4-9734-60056f253ffe', 'teleportTarget', 'ComputedRef<Element | undefined>', '', 'The resolved .origam-overlay-container element inside the target, or undefined when teleport is disabled (target=true) or the app is running on the server (SSR). Pass directly to <Teleport :to="teleportTarget">.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ed192079-1b70-45c1-af3f-396df6d686f1', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '474bac29-b298-44b8-8a22-53c19a71caa4', 'hostRef', 'Ref<HTMLElement | undefined>', '', 'Template ref to assign to the contenteditable element. The composable uses it to read and write innerHTML, attach the selectionchange listener, and focus the element before applying a format command.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8b5024e5-e2b8-4987-8a1f-78dc5dd55e34', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '474bac29-b298-44b8-8a22-53c19a71caa4', 'active', 'ITextareaRichActiveState', '', 'Reactive object tracking the formatting state at the current caret position. Properties: bold, italic, underline, code, link (booleans), listBullet, listOrdered (booleans), heading (0 | 1 | 2 | 3). Bind to toolbar button :active props.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ad22449b-51ed-4452-a283-537be63b865d', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '474bac29-b298-44b8-8a22-53c19a71caa4', 'format', '(command: TTextareaToolbarCommand, value?: string) => void', '', 'Apply a formatting command. Delegates to document.execCommand for bold, italic, underline, lists, and headings. Handles link creation (value = URL) and inline code toggling (insertHTML). Calls onFormat and onUpdate after every change.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6e2e4d27-4d52-4f8b-9d0a-83ea8fa5f7ea', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '474bac29-b298-44b8-8a22-53c19a71caa4', 'isFormatActive', '(command: TTextareaToolbarCommand) => boolean', '', 'Returns whether the given command is active at the current caret position. Reads from the reactive active object — a convenience wrapper for toolbar binding.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c18c911c-050a-4b3d-b53f-8cbbcc1d9359', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '474bac29-b298-44b8-8a22-53c19a71caa4', 'setValue', '(html: string) => void', '', 'Imperatively update the contenteditable innerHTML with sanitised HTML. No-ops when hostRef is unset or when the content is already identical (avoids cursor jump).', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b0aa35e8-6e8b-4697-9f2b-d47cd633af13', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '474bac29-b298-44b8-8a22-53c19a71caa4', 'onInput / onKeydown / onPaste', '(event) => void', '', 'Event handlers to bind on the host element. onInput emits sanitised HTML. onKeydown intercepts Cmd/Ctrl+B/I/U/E/K and Cmd+Shift+7/8 for list shortcuts. onPaste strips HTML to sanitised form (or escapes plain text) before inserting.', 5, false, NULL, NULL);
