INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6a4beefe-393f-4a92-9200-db089e5d3427', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'f7149be2-f10b-4542-8bdf-14a9f2dc0b71', 'scrollToIndex', '(index: number, options?: Partial<IGoToOptions>) => void', '', 'Programmatically scroll the container to a specific item index. Defers the scroll if the list has not yet measured (first render not complete). Pass `{ duration: 0 }` for instant scroll.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7b4babeb-ddc0-4ced-827a-7abd9459b8e9', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'f7149be2-f10b-4542-8bdf-14a9f2dc0b71', 'handleScroll', '() => void', '', 'Bind to the `scroll` event of the container element. Computes scroll velocity and triggers visible-items recalculation.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a9882885-f143-4024-af74-ee752860be7a', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'f7149be2-f10b-4542-8bdf-14a9f2dc0b71', 'handleScrollend', '() => void', '', 'Bind to the `scrollend` event. Resets scroll velocity and recalculates the visible window.', 7, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cd327c15-c950-421c-b64b-683bd814c091', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'f7149be2-f10b-4542-8bdf-14a9f2dc0b71', 'handleItemResize', '(index: number, height: number) => void', '', 'Call when a rendered item changes its measured height. Updates the size cache and triggers an offset recalculation. Wire via a ResizeObserver on each rendered row.', 8, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b0d47be2-3563-498b-91c3-9d1a3869499f', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'f03cd054-a631-4933-817c-67bdc39c42e7', '(model)', 'Ref<TInnerVal<Inner>> & { readonly externalValue: Props[Prop] }', '', 'A writable computed ref. Reading it returns the current value (controlled or internal). Writing it updates the internal ref and emits `update:prop`. The `externalValue` accessor returns the raw prop value without transformIn applied.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('83a422b5-44a5-473e-8fa6-98a99fccf250', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '8a7d7897-1e03-4334-8360-6eeb5b71dd1e', 'patternUrl', 'ComputedRef<string>', '', 'CSS `url("data:image/svg+xml,…")` string. Bind to `background-image` on any container element, or pass to `install()`. Recomputes reactively when options change.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('92b818a6-8b6b-4d57-9ae3-cb55945461df', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '8a7d7897-1e03-4334-8360-6eeb5b71dd1e', 'install', '(target?: HTMLElement) => HTMLElement | null', '', 'Inject a full-cover `<div>` layer with `position: absolute; inset: 0` and the pattern as background-image into `target` (defaults to document.body). Sets `position: relative` on the target if it is `static`. Returns the created layer element, or null during SSR.', 1, false, NULL, NULL);
