INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6d7c352f-121b-40d9-bca8-2607896fb522', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'f6a679cb-0ef3-413f-bb26-fa100126dda6', 'list', 'types.detail.file_field_display.list', 'Default. Renders each selected file as a card in a vertical stack below the field. Suitable when filenames and per-file actions (remove, download, progress) need to be visible.', 0, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('488d2374-e79e-459b-9506-3b6f744b19e6', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'f6a679cb-0ef3-413f-bb26-fa100126dda6', 'chips', 'types.detail.file_field_display.chips', 'Renders each selected file as a closable <OrigamChip> inline inside the field. Compact mode — best for forms where many files can be selected but vertical space is limited.', 1, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3281214e-ea6b-499a-8c76-a699893d0ede', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', 'f6a679cb-0ef3-413f-bb26-fa100126dda6', 'counter', 'types.detail.file_field_display.counter', 'Shows a single "N files selected" line with an <OrigamCounter>. Most compact mode — use when the file names are irrelevant to the user after selection.', 2, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('389150b4-d5b4-4ac0-b2c3-42eb9d45c55b', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '3d715334-8bbf-4b61-a41e-b82ec991dd75', 'false', 'types.detail.file_size.false', 'File sizes are not displayed. This is the default behaviour when the showSize prop is omitted.', 0, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('37401047-7aaf-4e51-9b37-b69760151edb', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '3d715334-8bbf-4b61-a41e-b82ec991dd75', 'true', 'types.detail.file_size.true', 'File sizes are displayed using the SI divisor (1 000) — KB, MB, GB.', 1, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4b4223c8-dbf7-4fee-946c-43a64ce23435', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '3d715334-8bbf-4b61-a41e-b82ec991dd75', '1000', 'types.detail.file_size.1000', 'Explicit SI (decimal) units: 1 KB = 1 000 bytes, 1 MB = 1 000 000 bytes. Matches the marketing convention used by most storage providers.', 2, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fc0b5a2a-5ea8-461d-9fcb-f3a942d8a233', '2026-11-02 07:35:25.023852+00', '2026-11-02 07:35:25.023852+00', '3d715334-8bbf-4b61-a41e-b82ec991dd75', '1024', 'types.detail.file_size.1024', 'Binary / IEC units: 1 KiB = 1 024 bytes, 1 MiB = 1 048 576 bytes. Traditional computing convention; more accurate for OS-reported file sizes.', 3, false, NULL, NULL);
